// Generated by gen.js – do not edit by hand.
window.LEVELS = [{"key":"ielts-ac","name":"IELTS Academic","short":"IELTS AC","quiz":"IELTS Academic","facts":0},{"key":"ielts-gt","name":"IELTS General Training","short":"IELTS GT","quiz":"IELTS General Training","facts":1},{"key":"toeic","name":"TOEIC (4 skills)","short":"TOEIC","quiz":"TOEIC","facts":2},{"key":"toefl","name":"TOEFL iBT (2026)","short":"TOEFL","quiz":"TOEFL iBT","facts":3},{"key":"aptis-g","name":"Aptis ESOL General","short":"Aptis G","quiz":"Aptis General","facts":4},{"key":"aptis-a","name":"Aptis ESOL Advanced","short":"Aptis A","quiz":"Aptis Advanced","facts":5},{"key":"b2","name":"B2 First","short":"B2 First","quiz":"B2 First","facts":6},{"key":"c1","name":"C1 Advanced","short":"C1 Adv","quiz":"C1 Advanced","facts":7},{"key":"vstep","name":"VSTEP.3-5","short":"VSTEP","quiz":"VSTEP","facts":8},{"key":"lingua","name":"Linguaskill","short":"Lingua","quiz":"Linguaskill","facts":9}];
window.FACTS = [{"id":"1","name":"IELTS Academic","groups":[{"cat":"Official holder and organiser","items":["IELTS is jointly owned by three organisations: the British Council, IDP IELTS and Cambridge University Press & Assessment.","In Vietnam, IELTS is organised by the British Council and IDP.","Prep schools such as IZONE or ZIM teach IELTS courses, but they are not official IELTS test organisers."]},{"cat":"Name of the test","items":["IELTS stands for International English Language Testing System.","IELTS has two versions: Academic and General Training."]},{"cat":"Skills, parts and time","items":["IELTS Academic tests 4 skills: Listening, Reading, Writing and Speaking.","The whole test takes about 2 hours 45 minutes.","Listening (about 30 minutes), Reading (60 minutes) and Writing (60 minutes) are taken one after another, with no breaks.","Speaking takes 11–14 minutes and can be on the same day or up to 7 days before or after the other skills."]},{"cat":"Validity of results","items":["There is no printed expiry date, but IELTS recommends that organisations accept results for up to 2 years.","The result document is called a Test Report Form (TRF), not a certificate."]},{"cat":"Main target test-takers","items":["IELTS Academic is for people who want to study at university (undergraduate or postgraduate level).","It is also used for professional registration, for example by doctors and nurses who want to work abroad."]},{"cat":"Listening – what candidates do (same for Academic and General Training)","items":["Listening has 4 parts with 10 questions each (40 questions), and every recording is heard only once.","Part 1: a conversation between two people in an everyday situation (e.g. booking a holiday).","Part 2: one person talking about an everyday topic (e.g. a talk about local facilities).","Part 3: a conversation between up to 4 people in a study situation (e.g. students and a tutor).","Part 4: one person giving an academic talk, like a university lecture.","Question types include multiple choice, matching, map/plan labelling, form or note completion and short answers."]},{"cat":"Reading – what candidates do","items":["Academic Reading has 3 long passages and 40 questions in 60 minutes.","Texts come from books, journals, magazines, newspapers and online sources, written for non-specialist readers.","Question types include True/False/Not Given (facts), Yes/No/Not Given (the writer’s views), matching headings and completing summaries or diagrams.","There is no extra time to copy Reading answers."]},{"cat":"Writing – what candidates do","items":["Task 1: describe visual information (a graph, table, chart, diagram, process or map) in at least 150 words, in about 20 minutes.","Task 2: write an essay giving an opinion or discussing a problem in at least 250 words, in about 40 minutes.","Task 2 counts twice as much as Task 1."]},{"cat":"Speaking – what candidates do (same for Academic and General Training)","items":["Speaking is a face-to-face interview with one examiner (or by video call at some centres) and is always marked by a person, not a computer.","Part 1 (4–5 minutes): answer questions about familiar topics such as home, work, studies or hobbies.","Part 2 (3–4 minutes): receive a cue card, prepare for 1 minute, then speak for up to 2 minutes.","Part 3 (4–5 minutes): discuss more abstract questions linked to the Part 2 topic."]},{"cat":"CEFR range and B2 / C1 scores","items":["Each skill and the overall result are given as a band from 0 to 9, in half bands.","IELTS covers about B1 to C2; it does not measure A1 or A2 reliably.","B2 = band 5.5–6.5.","C1 = band 7.0–8.0.","(For reference: B1 = 4.0–5.0; C2 = 8.5–9.0.)"]},{"cat":"Important facts to remember (what makes it different)","items":["Academic and General Training have the same Listening and Speaking tests; only Reading and Writing are different.","The overall band is the average of the four skills, rounded to the nearest half band (6.25 → 6.5; 6.75 → 7.0).","There is no pass or fail; each university or employer sets its own minimum band.","Since 29 March 2025, IELTS in Vietnam is taken only on computer.","One Skill Retake lets candidates retake one skill once, within 60 days of the original test."]}]},{"id":"2","name":"IELTS General Training","groups":[{"cat":"Official holder and organiser","items":["IELTS General Training has the same owners as IELTS Academic: the British Council, IDP IELTS and Cambridge University Press & Assessment.","In Vietnam, it is organised by the British Council and IDP."]},{"cat":"Name of the test","items":["General Training is one of the two versions of IELTS (International English Language Testing System)."]},{"cat":"Skills, parts and time","items":["General Training tests 4 skills: Listening, Reading, Writing and Speaking.","The whole test takes about 2 hours 45 minutes – the same as IELTS Academic."]},{"cat":"Validity of results","items":["IELTS recommends accepting results for up to 2 years; there is no printed expiry date."]},{"cat":"Main target test-takers","items":["General Training is mainly for people who want to migrate, work or train in an English-speaking country.","It is used for migration to countries such as Australia, Canada, New Zealand and the UK.","It is also used for study or training below degree level; people applying for a degree take IELTS Academic."]},{"cat":"Listening and Speaking","items":["Listening and Speaking are exactly the same as in IELTS Academic (4 Listening parts, 40 questions heard once; 3 Speaking parts, 11–14 minutes)."]},{"cat":"Reading – what candidates do","items":["GT Reading has 3 sections and 40 questions in 60 minutes, and the sections get harder.","Section 1: short texts about everyday life, such as notices, advertisements and timetables.","Section 2: two texts about work, such as job descriptions, contracts or training materials.","Section 3: one longer text on a general-interest topic."]},{"cat":"Writing – what candidates do","items":["Task 1: write a letter (informal, semi-formal or formal) of at least 150 words, covering 3 bullet points, in about 20 minutes.","Task 2: write an essay on a general topic in at least 250 words, in about 40 minutes.","Task 2 counts twice as much as Task 1."]},{"cat":"CEFR range and B2 / C1 scores","items":["Results are given in bands from 0 to 9, like IELTS Academic.","B2 = band 5.5–6.5.","C1 = band 7.0–8.0."]},{"cat":"Important facts to remember (what makes it different)","items":["GT Reading needs more correct answers than Academic Reading for the same band (e.g. 30/40 = band 6 in GT but band 7 in Academic).","The biggest difference from Academic is Writing Task 1: a letter instead of describing a graph."]}]},{"id":"3","name":"TOEIC (4 skills)","groups":[{"cat":"Official holder and organiser","items":["TOEIC is developed by ETS (Educational Testing Service), USA – the same organisation that makes TOEFL.","In Vietnam, TOEIC is organised by IIG Vietnam, with approval from MOET."]},{"cat":"Name of the test","items":["TOEIC stands for Test of English for International Communication.","The 4-skill TOEIC is made of two separate tests: TOEIC Listening & Reading and TOEIC Speaking & Writing."]},{"cat":"Skills, parts and time","items":["TOEIC Listening & Reading: 200 multiple-choice questions in about 2 hours (Listening about 45 minutes, Reading 75 minutes).","TOEIC Speaking & Writing: about 80 minutes on computer (Speaking about 20 minutes, Writing about 60 minutes)."]},{"cat":"Validity of results","items":["ETS recommends that TOEIC scores are used for up to 2 years."]},{"cat":"Main target test-takers","items":["TOEIC measures English for the workplace and international business.","It is mostly used by employers, and by many Vietnamese universities as a graduation requirement."]},{"cat":"Listening – what candidates do (100 questions)","items":["Part 1 – Photographs (6 questions): choose the sentence that best describes a photo.","Part 2 – Question–Response (25 questions): hear a question and choose the best reply from only 3 options.","Part 3 – Conversations (39 questions): answer 3 questions about each short conversation.","Part 4 – Talks (30 questions): answer 3 questions about each short talk, such as an announcement."]},{"cat":"Reading – what candidates do (100 questions)","items":["Part 5 – Incomplete Sentences (30 questions): choose the word or phrase that completes a sentence.","Part 6 – Text Completion (16 questions): fill gaps in short texts, including whole-sentence gaps.","Part 7 – Reading Comprehension (54 questions): answer questions on single, double and triple texts (emails, ads, articles, chats)."]},{"cat":"Speaking – what candidates do (11 questions)","items":["Read a text aloud (2 questions).","Describe a picture (2 questions).","Respond to questions (3 questions).","Respond to questions using information provided, such as a schedule (3 questions).","Express an opinion (1 question): prepare for 45 seconds, then speak for 60 seconds."]},{"cat":"Writing – what candidates do (8 questions)","items":["Write a sentence based on a picture, using two given words (5 questions, 8 minutes in total).","Respond to a written request, i.e. reply to an email (2 questions, 10 minutes each).","Write an opinion essay of usually at least 300 words (1 question, 30 minutes)."]},{"cat":"CEFR range and B2 / C1 scores","items":["Listening and Reading are scored 5–495 each, for a total of 10–990; Speaking and Writing are scored 0–200 each.","TOEIC covers A1 to C1; it does not report C2.","B2 = Listening & Reading total 785–940; Speaking 160–170; Writing 150–170.","C1 = Listening & Reading total 945 or above; Speaking 180 or above; Writing 180 or above."]},{"cat":"Important facts to remember (what makes it different)","items":["Listening & Reading and Speaking & Writing are two separate tests – candidates can take L&R on its own.","A high L&R score does not prove good speaking or writing, because the two tests measure different skills.","There is no pass or fail.","At IIG Vietnam, candidates must wait at least 5 working days between two TOEIC tests."]}]},{"id":"4","name":"TOEFL iBT (new version, from 21 January 2026)","groups":[{"cat":"Official holder and organiser","items":["TOEFL is developed by ETS (Educational Testing Service), USA – the same organisation that makes TOEIC.","In Vietnam, IIG Vietnam sells vouchers for TOEFL iBT at test centres."]},{"cat":"Name of the test","items":["TOEFL stands for Test of English as a Foreign Language; iBT means internet-Based Test.","A new, redesigned TOEFL iBT started on 21 January 2026."]},{"cat":"Skills, parts and time","items":["TOEFL iBT tests 4 skills in this order: Reading → Listening → Writing → Speaking.","The base testing time is about 90 minutes (under 2 hours in total).","Reading about 30 minutes; Listening about 29 minutes; Writing 23 minutes; Speaking 8 minutes."]},{"cat":"Validity of results","items":["TOEFL iBT scores are valid for 2 years."]},{"cat":"Main target test-takers","items":["TOEFL iBT is mainly for students who want to study at English-speaking universities.","It is accepted by more than 13,000 institutions in over 160 countries."]},{"cat":"Reading – what candidates do","items":["Complete the Words: fill in the missing letters of words in a short text.","Read in Daily Life: read short everyday texts (e.g. notices, emails) and answer questions.","Read an Academic Passage: read a short academic text and answer questions."]},{"cat":"Listening – what candidates do","items":["Listen and Choose a Response: hear a short sentence and choose the best reply.","Listen to a Conversation, an Announcement and an Academic Talk, then answer questions."]},{"cat":"Writing – what candidates do","items":["Build a Sentence: put words in the correct order to make a sentence.","Write an Email (7 minutes).","Write for an Academic Discussion: post a reply in an online class discussion (10 minutes)."]},{"cat":"Speaking – what candidates do","items":["Listen and Repeat: hear 7 sentences and repeat each one.","Take an Interview: answer 4 questions, 45 seconds each, with no preparation time."]},{"cat":"CEFR range and B2 / C1 scores","items":["Since 21 January 2026, each section and the overall score are reported on a 1–6 scale, in half-point steps.","TOEFL iBT covers A1 to C2.","B2 = 4.0–4.5.","C1 = 5.0–5.5.","(For reference: B1 = 3.0–3.5; C2 = 6.)"]},{"cat":"Important facts to remember (what makes it different)","items":["Reading and Listening are adaptive: the second stage becomes easier or harder depending on the candidate’s earlier answers.","Speaking and Writing are scored by AI together with human raters.","Results come within 72 hours.","TOEFL iBT can be taken at a test centre or at home (Home Edition); the Paper Edition ended in January 2024.","Until January 2028, the score report also shows a comparable score on the old 0–120 scale."]}]},{"id":"5","name":"Aptis ESOL General","groups":[{"cat":"Official holder and organiser","items":["Aptis is developed and owned by the British Council.","In Vietnam, Aptis ESOL is organised by the British Council, together with partner institutions approved by MOET."]},{"cat":"Name of the test","items":["The certificated test for individuals is called Aptis ESOL General; it is regulated by Ofqual (the exam regulator in England).","Plain “Aptis” is the version that organisations buy to test their own staff or students."]},{"cat":"Skills, parts and time","items":["Aptis General has 5 components: Core (grammar and vocabulary), Reading, Listening, Writing and Speaking.","Times: Core 25 minutes, Reading 35, Listening 40, Writing 50, Speaking 12 – a total of 162 minutes.","Aptis ESOL is taken on computer in supervised sessions."]},{"cat":"Validity of results","items":["Aptis results have no expiry date; the British Council recommends that organisations accept them for up to 2 years."]},{"cat":"Main target test-takers","items":["Aptis ESOL is for people aged 16 and over who need to show their English level to a university, school or employer.","Organisations (universities, companies) also use Aptis to test large groups."]},{"cat":"Core – what candidates do","items":["Grammar: 25 questions, each with 3 options.","Vocabulary: 25 items – match words to meanings, definitions, sentences or collocations."]},{"cat":"Reading – what candidates do (4 parts)","items":["Part 1: choose the right word to complete 5 short sentences.","Part 2: put sentences in the correct order to make a story or text.","Part 3: match people’s opinions to statements.","Part 4: match headings to the paragraphs of a long text (about 750 words)."]},{"cat":"Listening – what candidates do (4 parts)","items":["Every recording can be played up to twice.","Part 1: listen to 13 short recordings and find specific information (a number, time or place).","Part 2: match 4 speakers to what they say.","Part 3: listen to a discussion and decide if each opinion belongs to the man, the woman or both.","Part 4: listen to 2 longer monologues and answer questions about the speaker’s attitude or opinion."]},{"cat":"Writing – what candidates do (4 parts)","items":["Part 1: answer 5 short messages in 1–5 words each (spelling and grammar are not marked).","Part 2: fill in a form with personal information (20–30 words).","Part 3: reply to 3 questions on a social network (30–40 words each).","Part 4: write an informal email to a friend (40–50 words) and a formal email (120–150 words) about the same situation."]},{"cat":"Speaking – what candidates do (4 parts)","items":["Part 1: answer 3 personal questions (30 seconds each).","Part 2: describe a photo and answer 2 related questions (45 seconds each).","Part 3: compare two photos and answer 2 related questions (45 seconds each).","Part 4: look at a picture and answer 3 abstract questions; prepare for 1 minute, then speak for 2 minutes."]},{"cat":"CEFR range and B2 / C1 scores","items":["Each skill is scored 0–50; the four skills add up to a total out of 200.","Aptis General covers A1 to B2, plus a “C” result (A0 is reported below A1).","B2 = from 34 (Listening), 38 (Reading), 40 (Writing) or 41 (Speaking) out of 50.","C1 is not separated: candidates above B2 receive “C” = from 42 (Listening), 46 (Reading), 48 (Writing) or 48 (Speaking)."]},{"cat":"Important facts to remember (what makes it different)","items":["Aptis is modular: organisations choose which skills to test, but the Core is always included.","The Core gets a score only (no CEFR level) and is not added to the /200 total; a strong Core score can lift a borderline skill to the next level.","The overall CEFR level is given only if all four skills are taken.","The score needed for each level is different for each skill.","Aptis General does not separate C1 and C2 – it only gives “C”.","Aptis is not accepted for UK visas."]}]},{"id":"6","name":"Aptis ESOL Advanced","groups":[{"cat":"Official holder and organiser","items":["Aptis ESOL Advanced is developed and owned by the British Council.","In Vietnam, it is organised by the British Council and MOET-approved partners."]},{"cat":"Name of the test","items":["The certificated version for individuals is called Aptis ESOL Advanced."]},{"cat":"Skills, parts and time","items":["Aptis Advanced has the same 5 components as General: Core, Reading, Listening, Writing and Speaking.","Times: Core 25 minutes, Reading 60, Listening 30, Writing 45, Speaking 10 – a total of 170 minutes."]},{"cat":"Validity of results","items":["Results have no expiry date; the British Council recommends accepting them for up to 2 years."]},{"cat":"Main target test-takers","items":["Aptis Advanced is for people aged 16+ with a high level of English who need it for work, training or study."]},{"cat":"Core – what candidates do","items":["The Core is the same as in Aptis General: 25 grammar questions and 25 vocabulary items."]},{"cat":"Reading – what candidates do (4 parts)","items":["Part 1: match people’s opinions to statements.","Part 2: match headings to the paragraphs of a long text (about 750 words).","Part 3: fill 5 gaps in a text (about 300 words), choosing from 3 options.","Part 4: fill 6 gaps in two short texts on the same topic."]},{"cat":"Listening – what candidates do (4 parts)","items":["Part 1: 5 short recordings, 1 question each (can be played up to twice).","Part 2: 3 monologues about opinions and attitudes, 2 questions each (up to twice).","Part 3: a discussion – decide if each opinion belongs to the man, the woman or both (played only once).","Part 4: 2 monologues – choose answers from a table (played only once)."]},{"cat":"Writing – what candidates do (3 parts)","items":["Part 1: reply to 3 questions on a social network (30–40 words each).","Part 2: write a formal email to an authority, using notes (120–150 words).","Part 3: write an informative website article (180–220 words)."]},{"cat":"Speaking – what candidates do (4 parts)","items":["Part 1: compare two pictures and answer 2 related questions (45 seconds each).","Part 2: answer 3 abstract questions; prepare for 1 minute, then speak for 2 minutes.","Part 3: give a presentation using “for” and “against” points; prepare for 1 minute, then speak for 90 seconds.","Part 4: answer 1 follow-up question, with no preparation (45 seconds)."]},{"cat":"CEFR range and B2 / C1 scores","items":["Each skill is scored 0–50; the total is out of 200 (the Core is not included).","Aptis Advanced covers B1 to C2.","B2 = from 24 (Listening), 28 (Reading), 37 (Writing) or 37 (Speaking) out of 50.","C1 = from 38 (Listening), 40 (Reading), 44 (Writing) or 44 (Speaking) out of 50.","C2 needs a full 50/50 in that skill."]},{"cat":"Important facts to remember (what makes it different)","items":["Aptis Advanced is the only Aptis test that reports C1 and C2 separately.","It is the only Aptis test with Listening parts played only once (Parts 3 and 4).","Writing includes a website article, and Speaking includes a short presentation.","Candidates below B1 receive a report (A0–A2), not a certificate."]}]},{"id":"7","name":"B2 First (formerly FCE)","groups":[{"cat":"Official holder and organiser","items":["B2 First is made by Cambridge University Press & Assessment (part of the University of Cambridge).","It is taken at Cambridge-authorised exam centres."]},{"cat":"Name of the test","items":["The old name was First Certificate in English (FCE); it was renamed B2 First in September 2017.","There are two versions: B2 First (for adults) and B2 First for Schools (for school-age learners)."]},{"cat":"Skills, parts and time","items":["B2 First has 4 papers – Reading and Use of English, Writing, Listening and Speaking – but 5 scores, because Reading and Use of English are scored separately.","The whole exam takes about 3.5 hours.","Reading and Use of English 1 hour 15 minutes; Writing 1 hour 20 minutes; Listening about 40 minutes; Speaking 14 minutes per pair."]},{"cat":"Validity of results","items":["The B2 First certificate does not expire, although universities or visa offices may set their own time limits."]},{"cat":"Main target test-takers","items":["B2 First is for learners at upper-intermediate level (B2) who want to show they can use English to study, work or live in an English-speaking country."]},{"cat":"Reading and Use of English – what candidates do (7 parts)","items":["Use of English parts: multiple-choice gap-fill (Part 1), open gap-fill (Part 2), word formation (Part 3) and key word transformation using 2–5 words (Part 4).","Reading parts: multiple choice on a long text (Part 5), put missing sentences back into a text (Part 6) and multiple matching (Part 7)."]},{"cat":"Writing – what candidates do (2 parts)","items":["Part 1: a compulsory essay, using two given ideas and one idea of your own (140–190 words).","Part 2: choose 1 of 3 tasks – an article, email/letter, review, or a report (B2 First) / a story (B2 First for Schools) (140–190 words)."]},{"cat":"Listening – what candidates do (4 parts)","items":["Every recording is heard twice.","Part 1: short extracts with multiple-choice questions; Part 2: sentence completion; Part 3: match 5 speakers to options; Part 4: an interview with multiple-choice questions."]},{"cat":"Speaking – what candidates do (4 parts)","items":["Candidates usually take Speaking in pairs, with two examiners.","Part 1: interview – answer personal questions (2 minutes).","Part 2: long turn – compare 2 photos for 1 minute, then comment briefly on the partner’s photos.","Part 3: collaborative task – discuss a topic with the partner and then make a decision.","Part 4: discussion – talk about wider questions linked to Part 3."]},{"cat":"CEFR range and B2 / C1 scores","items":["Results are reported on the Cambridge English Scale.","B2 First covers B1 to C1 (the target level is B2).","B2 = 160–179 (Grade C 160–172, Grade B 173–179).","C1 = 180–190 (Grade A).","140–159 gives a B1 certificate; below 140 there is no certificate."]},{"cat":"Important facts to remember (what makes it different)","items":["Speaking is in pairs with two examiners: the interlocutor asks the questions, and the assessor only listens and marks.","Every Listening recording is heard twice (unlike IELTS, TOEIC and VSTEP).","It tests Use of English (grammar and vocabulary) as a separate score.","Each of the 5 scores is worth 20%.","It can be taken on paper or on computer, and the certificate never expires."]}]},{"id":"8","name":"C1 Advanced (formerly CAE)","groups":[{"cat":"Official holder and organiser","items":["C1 Advanced is made by Cambridge University Press & Assessment.","It is taken at Cambridge-authorised exam centres."]},{"cat":"Name of the test","items":["The old name was Certificate in Advanced English (CAE); it was renamed C1 Advanced in September 2017.","The certificate still uses the name “Certificate in Advanced English”."]},{"cat":"Skills, parts and time","items":["C1 Advanced has 4 papers but 5 scores: Reading, Use of English, Writing, Listening and Speaking.","The whole exam takes about 3 hours 55 minutes.","Reading and Use of English 1 hour 30 minutes; Writing 1 hour 30 minutes; Listening about 40 minutes; Speaking 15 minutes per pair."]},{"cat":"Validity of results","items":["The C1 Advanced certificate does not expire."]},{"cat":"Main target test-takers","items":["C1 Advanced is for people who need a high level of English for university study or professional work (e.g. managers, researchers)."]},{"cat":"Reading and Use of English – what candidates do (8 parts)","items":["Use of English parts: multiple-choice gap-fill, open gap-fill, word formation and key word transformation using 3–6 words.","Reading parts: multiple choice on a long text, cross-text matching (compare opinions in 4 short texts), put missing paragraphs back into a text, and multiple matching."]},{"cat":"Writing – what candidates do (2 parts)","items":["Part 1: a compulsory essay – choose 2 of 3 points and say which is more important (220–260 words).","Part 2: choose 1 of 3 tasks – a letter/email, proposal, report or review (220–260 words)."]},{"cat":"Listening – what candidates do (4 parts)","items":["Every part is heard twice.","Part 1: 3 short extracts with multiple-choice questions (3 options); Part 2: sentence completion; Part 3: a conversation with multiple-choice questions (4 options); Part 4: two matching tasks for 5 speakers."]},{"cat":"Speaking – what candidates do (4 parts)","items":["Candidates take Speaking in pairs, with two examiners.","Part 1: interview (2 minutes).","Part 2: long turn – get 3 photos and talk about 2 of them for 1 minute.","Part 3: collaborative task – discuss with the partner and reach a decision.","Part 4: discussion on wider questions linked to Part 3."]},{"cat":"CEFR range and B2 / C1 scores","items":["Results are reported on the Cambridge English Scale.","C1 Advanced covers B2 to C2 (the target level is C1).","B2 = 160–179 (B2 certificate).","C1 = 180–199 (Grade C 180–192, Grade B 193–199).","200–210 gives Grade A and a C2 certificate."]},{"cat":"Important facts to remember (what makes it different)","items":["There is no Schools version of C1 Advanced.","Writing Part 2 includes a proposal, which B2 First does not have.","Speaking Part 2 uses 3 photos (B2 First uses 2).","It is accepted by over 11,000 organisations; Australia currently accepts only the paper-based version for visas."]}]},{"id":"9","name":"VSTEP (VSTEP.3-5)","groups":[{"cat":"Official holder and organiser","items":["VSTEP belongs to Vietnam’s Ministry of Education and Training (MOET); its format was set by Decision 729/QĐ-BGDĐT (2015).","It was developed by ULIS, Vietnam National University, Hanoi, under the National Foreign Languages Project.","It is organised by universities licensed by MOET (38 institutions in March 2025), e.g. ULIS-VNU, Hanoi University, Hue University of Foreign Languages, HCMC University of Education."]},{"cat":"Name of the test","items":["VSTEP stands for Vietnamese Standardized Test of English Proficiency.","VSTEP.3-5 means it gives Levels 3, 4 or 5 of Vietnam’s 6-level framework."]},{"cat":"Skills, parts and time","items":["VSTEP tests 4 skills: Listening, Reading, Writing and Speaking.","The whole test takes about 172 minutes: Listening about 40, Reading 60, Writing 60, Speaking 12.","It is now mostly taken on computer."]},{"cat":"Validity of results","items":["There is no national expiry date; the organisation that receives the certificate decides how long to accept it (Circular 09/2026)."]},{"cat":"Main target test-takers","items":["University students who need an English level to graduate.","Teachers, lecturers and public-sector staff who must meet English standards.","Master’s applicants (they need at least Level 3 / B1).","High-school students: Level 3 or higher can exempt them from the English graduation exam (since 2025)."]},{"cat":"Listening – what candidates do (3 parts, 35 multiple-choice questions, heard once)","items":["Part 1: short announcements, instructions and conversations (8 questions).","Part 2: 3 longer conversations (12 questions).","Part 3: 3 talks or lectures (15 questions)."]},{"cat":"Reading – what candidates do","items":["Read 4 passages and answer 10 multiple-choice questions for each (40 questions); the passages get harder."]},{"cat":"Writing – what candidates do (2 tasks)","items":["Task 1: write a letter or email of at least about 120 words (about 20 minutes, 1/3 of the Writing score).","Task 2: write an essay of at least 250 words (about 40 minutes, 2/3 of the Writing score)."]},{"cat":"Speaking – what candidates do (3 parts)","items":["Part 1 – Social interaction: answer questions on 2 familiar topics (3 minutes).","Part 2 – Solution discussion: choose the best of 3 solutions to a situation and explain why (4 minutes, including 1 minute to prepare).","Part 3 – Topic development: talk about a topic using a mind map, then answer follow-up questions (5 minutes, including 1 minute to prepare)."]},{"cat":"CEFR range and B2 / C1 scores","items":["Each skill is scored 0–10; the overall score is the average, rounded to 0.5.","VSTEP.3-5 covers B1 to C1 (Levels 3 to 5).","B2 (Level 4) = overall 6.0–8.0.","C1 (Level 5) = overall 8.5–10.","(For reference: B1 / Level 3 = 4.0–5.5; below 4.0 = no level.)"]},{"cat":"Important facts to remember (what makes it different)","items":["VSTEP is Vietnam’s own national test and is recognised mainly in Vietnam.","It is one exam for three levels – candidates do not choose B1, B2 or C1 before the test.","It is cheaper than international tests (e.g. about 1,800,000 VND at ULIS).","There is no picture-description task in Speaking.","All Listening and Reading questions are multiple choice."]}]},{"id":"10","name":"Linguaskill","groups":[{"cat":"Official holder and organiser","items":["Linguaskill is made by Cambridge University Press & Assessment.","In Vietnam, Linguaskill is organised by REAP JSC together with Cambridge, with MOET approval."]},{"cat":"Name of the test","items":["There are two versions: Linguaskill (everyday and academic English) and Linguaskill Business (it replaced the BEC exams).","A new version of Linguaskill started in autumn 2024."]},{"cat":"Skills, parts and time","items":["Linguaskill has 4 modules: Reading, Listening, Writing and Speaking.","Reading and Listening take about 40 minutes each (maximum 59); Writing 55 minutes; Speaking 16 minutes (plus 3 unmarked warm-up questions).","It is taken online, at an approved test centre or remotely with AI proctoring."]},{"cat":"Validity of results","items":["The Linguaskill certificate is digital and has no expiry date; each organisation decides how recent a result must be."]},{"cat":"Main target test-takers","items":["Linguaskill is mainly used by organisations – universities and employers – for admission, graduation and recruitment.","In Vietnam, B1 can exempt high-school students from the English graduation exam."]},{"cat":"Reading – what candidates do","items":["Answer adaptive tasks such as multiple choice, gap-fill, missing sentences/paragraphs and matching information across several texts."]},{"cat":"Listening – what candidates do","items":["Answer adaptive tasks such as multiple choice, sentence completion and matching speakers to information."]},{"cat":"Writing – what candidates do (2 parts)","items":["Part 1: write an email of at least 50 words (25% of the score).","Part 2: write an essay (or a report in Linguaskill Business) of at least 250 words (75% of the score)."]},{"cat":"Speaking – what candidates do (recorded on computer)","items":["Part 1 – Presentation: speak for 1 minute on a topic with 3 bullet points.","Part 2 – Summary and discussion: summarise 4 key points from an audio recording (40 seconds), then answer 3 follow-up questions.","Part 3 – Recommendation: read a friend’s or colleague’s message and recommend a solution.","Part 4 – Arguments: give arguments for and against a statement and reach a conclusion."]},{"cat":"CEFR range and B2 / C1 scores","items":["Each module gets a score, and the certificate shows an overall average.","The new Linguaskill covers B1 to C2; scores below 140 are shown as “Not reported”.","B2 = 160–179.","C1 = 180–199.","(For reference: B1 = 140–159; C2 = 200–210.)"]},{"cat":"Important facts to remember (what makes it different)","items":["Each module can be taken separately – candidates can take just one skill.","Reading and Listening are adaptive: questions get easier or harder depending on earlier answers.","Writing and Speaking are marked by computer and human examiners together (hybrid marking).","Results come from 3 working days after the test.","My Best Score shows the best result from retakes within 6 months.","It uses the same number line as B2 First and C1 Advanced (e.g. 175 = B2 on all three)."]}]}];
window.QUIZ = {"IELTS Academic":[{"t":"tf","q":"IELTS is jointly owned by the British Council, IDP IELTS and ETS.","a":false,"why":"IELTS is jointly owned by the British Council, IDP IELTS and Cambridge University Press & Assessment. ETS is the American organisation that makes TOEIC and TOEFL, not IELTS."},{"t":"tf","q":"Since 29 March 2025, IELTS in Vietnam can only be taken on computer.","a":true,"why":"The paper-based test ended in Vietnam on that date. Paper IELTS is also being phased out worldwide from 2026."},{"t":"gap","q":"The Listening test has ____ parts with ____ questions each, and each recording is heard ____.","a":["4","10","once"],"why":"4 parts × 10 questions = 40 questions. Candidates cannot hear a recording a second time."},{"t":"mc","q":"Which Listening part is an academic lecture given by one speaker?","opts":["Part 1","Part 2","Part 3","Part 4"],"a":3,"why":"Parts 1 and 2 are everyday situations. Part 3 is an educational conversation with up to 4 speakers. Part 4 is the lecture."},{"t":"tf","q":"Candidates taking IELTS on computer get 10 extra minutes to transfer their Listening answers.","a":false,"why":"On computer there is no transfer time, only 2 minutes at the end to check answers. The 10 extra minutes were for the paper test, where answers had to be copied onto an answer sheet."},{"t":"mc","q":"How many question types are used in Academic Reading?","opts":["6","8","11","14"],"a":2,"why":"Academic Reading uses 11 types, such as True/False/Not Given and matching headings. Listening uses 6."},{"t":"tf","q":"Yes/No/Not Given questions check facts in the text.","a":false,"why":"Yes/No/Not Given questions check the writer’s views. True/False/Not Given checks facts. Yes/No/Not Given checks opinions or claims of the writer."},{"t":"mc","q":"In Speaking Part 2, how long does the candidate have to prepare?","opts":["30 seconds","1 minute","2 minutes","No preparation time"],"a":1,"why":"The candidate gets a cue card, prepares for 1 minute (notes allowed), then speaks for up to 2 minutes."},{"t":"mc","q":"A candidate’s four skill bands average 6.25. What is the overall band?","opts":["6.0","6.25","6.5","7.0"],"a":2,"why":"An average ending in .25 rounds up to the next half band. (6.75 would round up to 7.0; 6.125 would round down to 6.0.)"},{"t":"mc","q":"Which IELTS band range is linked to CEFR B2?","opts":["4.0–5.0","5.5–6.5","7.0–8.0","8.5–9.0"],"a":1,"why":"B1 = 4.0–5.0, B2 = 5.5–6.5, C1 = 7.0–8.0, C2 = 8.5–9.0. IELTS does not reliably measure A1 or A2."},{"t":"tf","q":"An IELTS Test Report Form has a printed expiry date 2 years after the test.","a":false,"why":"There is no printed expiry date. IELTS recommends that organisations accept results for up to 2 years. “2 years” is advice to universities and employers. Each organisation decides for itself."},{"t":"mc","q":"How long does the whole IELTS test take?","opts":["2 hours","2 hours 30 minutes","2 hours 45 minutes","3 hours 30 minutes"],"a":2,"why":"Listening, Reading and Writing are taken one after another with no breaks; Speaking adds 11–14 minutes."},{"t":"mc","q":"What is the official name for band 7?","opts":["Competent user","Good user","Very good user","Expert user"],"a":1,"why":"Band 6 = Competent user, band 8 = Very good user, band 9 = Expert user."},{"t":"mc","q":"Which of these is NOT one of the four Speaking criteria?","opts":["Fluency and Coherence","Lexical Resource","Pronunciation","Task Response"],"a":3,"why":"Task Response is a Writing criterion (Task 2)."},{"t":"mc","q":"Which version of IELTS tests only Speaking and Listening and gives a Pass or Fail?","opts":["IELTS for UKVI","IELTS Online","IELTS Life Skills","One Skill Retake"],"a":2,"why":"IELTS Life Skills is offered at A1, A2 and B1 for some UK visas."},{"t":"mc","q":"Which organisations jointly own the IELTS exam?","opts":["British Council, IDP IELTS and Cambridge University Press & Assessment","ETS and IIG Vietnam","British Council and ETS","IDP IELTS and IIG Vietnam"],"a":0,"why":"ETS makes TOEIC and TOEFL; IIG Vietnam runs TOEIC in Vietnam.","reverse":false},{"t":"mc","q":"Which exam has two versions whose Listening and Speaking tests are exactly the same?","opts":["TOEIC","TOEFL iBT","IELTS","Aptis"],"a":2,"why":"IELTS Academic and General Training share Listening and Speaking; only Reading and Writing differ.","reverse":true},{"t":"mc","q":"In IELTS Reading, which question type asks whether a statement agrees with the writer’s views?","opts":["True / False / Not Given","Yes / No / Not Given","Matching headings","Sentence completion"],"a":1,"why":"True/False/Not Given checks facts; Yes/No/Not Given checks the writer’s views.","reverse":false},{"t":"mc","q":"A candidate’s four IELTS skill bands average 6.25. What is her overall band?","opts":["6.0","6.25","6.5","7.0"],"a":2,"why":"An average ending in .25 rounds up to the next half band.","reverse":false},{"t":"mc","q":"Which exam reports its results on a document called a Test Report Form (TRF)?","opts":["TOEIC","IELTS","B2 First","VSTEP"],"a":1,"why":"IELTS recommends that organisations accept a TRF for 2 years.","reverse":true},{"t":"mc","q":"In IELTS Listening, how many times is each recording heard?","opts":["Once only","Twice","Up to twice – the candidate chooses","Three times"],"a":0,"why":"B2 First and C1 Advanced recordings are heard twice; Aptis General recordings up to twice.","reverse":false},{"t":"mc","q":"Which IELTS Writing task counts twice as much as the other?","opts":["Task 1","Task 2","Both tasks count equally","It depends on the candidate"],"a":1,"why":"Task 2 (the essay) counts twice as much as Task 1.","reverse":false}],"IELTS General Training":[{"t":"mc","q":"Who is IELTS General Training mainly for?","opts":["People applying for a university degree","People who want to migrate, work or train abroad","Employees of international companies in Japan","High-school students in Vietnam"],"a":1,"why":"General Training is used for migration (e.g. Australia, Canada, New Zealand, the UK), work, and training below degree level."},{"t":"tf","q":"General Training candidates take a different Listening test from Academic candidates.","a":false,"why":"Academic and General Training have the same Listening and Speaking tests. Only Reading and Writing are different in the two versions."},{"t":"gap","q":"GT Reading Section 1 is about everyday life, Section 2 is about ____, and Section 3 is one longer general-interest text.","a":["work"],"why":"Section 2 has two workplace texts, such as job descriptions or contracts."},{"t":"tf","q":"For the same band, GT Reading needs more correct answers than Academic Reading.","a":true,"why":"GT texts are easier, so candidates must get more answers right to reach the same band."},{"t":"mc","q":"About 30 correct answers out of 40 in GT Reading gives:","opts":["Band 5","Band 6","Band 7","Band 8"],"a":1,"why":"In Academic Reading, 30/40 gives band 7. In GT Reading, the same score gives only band 6."},{"t":"mc","q":"What is GT Writing Task 1?","opts":["Describing a graph or chart","Writing a letter","Writing a report","Writing a story"],"a":1,"why":"The letter can be informal, semi-formal or formal. Describing a graph is Academic Task 1."},{"t":"gap","q":"The GT letter task gives ____ bullet points that the candidate must cover.","a":["3"],"why":"The letter must be at least 150 words, and all three bullet points should be covered."},{"t":"tf","q":"One Skill Retake lets a candidate retake one skill as many times as they like within a year.","a":false,"why":"One Skill Retake lets a candidate retake one skill once, within 60 days of the original test. The candidate receives a new Test Report Form and can use either result."},{"t":"mc","q":"Which of these is NOT a usual reason for taking IELTS General Training?","opts":["Migrating to Canada","Working in Australia","Studying for a master’s degree","Training below degree level"],"a":2,"why":"People who want to study for a degree normally take IELTS Academic."},{"t":"mc","q":"How many questions are in GT Reading?","opts":["30","35","40","50"],"a":2,"why":"GT Reading takes 60 minutes and has 3 sections."},{"t":"mc","q":"How do the GT Reading sections change from Section 1 to Section 3?","opts":["They get easier","They get more difficult","They stay at the same level","Section 2 is always the hardest"],"a":1,"why":"Section 1 has short everyday texts; Section 3 is one longer, more complex text."},{"t":"mc","q":"Which Writing task carries more marks?","opts":["Task 1","Task 2","Both carry the same marks","It depends on the candidate"],"a":1,"why":"Task 2 counts twice as much as Task 1."},{"t":"mc","q":"Which CEFR level matches IELTS 7.0–8.0?","opts":["B1","B2","C1","C2"],"a":2,"why":"B2 = 5.5–6.5; C1 = 7.0–8.0; C2 = 8.5–9.0."},{"t":"mc","q":"What is the official name of the IELTS result document?","opts":["Certificate","Statement of Results","Test Report Form","Score Report"],"a":2,"why":"“Statement of Results” is the name Cambridge uses for B2 First and C1 Advanced."}],"TOEIC":[{"t":"mc","q":"What does TOEIC stand for?","opts":["Test of English for International Communication","Test of English as a Foreign Language","Test of English for International Companies","Test of English in International Contexts"],"a":0,"why":"“Test of English as a Foreign Language” is TOEFL. Both tests are made by ETS."},{"t":"mc","q":"Which organisation runs TOEIC in Vietnam?","opts":["British Council","IDP","IIG Vietnam","ULIS – VNU Hanoi"],"a":2,"why":"IIG Vietnam runs TOEIC with approval from MOET. The British Council and IDP run IELTS; ULIS developed VSTEP."},{"t":"tf","q":"TOEIC Listening & Reading and TOEIC Speaking & Writing are two separate tests.","a":true,"why":"Candidates can take Listening & Reading without Speaking & Writing. Each has its own score."},{"t":"gap","q":"TOEIC Listening & Reading has ____ multiple-choice questions and lasts about ____ hours.","a":["200","2"],"why":"100 Listening questions (about 45 minutes) + 100 Reading questions (75 minutes)."},{"t":"mc","q":"Which Listening part has only 3 answer options?","opts":["Part 1 – Photographs","Part 2 – Question–Response","Part 3 – Conversations","Part 4 – Talks"],"a":1,"why":"Part 2 has 25 questions with 3 options. All other parts have 4 options."},{"t":"mc","q":"How many questions are in Part 7 (Reading Comprehension)?","opts":["16","30","39","54"],"a":3,"why":"54 questions: 29 on single passages and 25 on double or triple passages."},{"t":"gap","q":"TOEIC Speaking has ____ questions and lasts about ____ minutes.","a":["11","20"],"why":"Tasks: read a text aloud, describe a picture, respond to questions, respond using information, express an opinion."},{"t":"mc","q":"In the “Express an opinion” task, the candidate prepares for ___ and speaks for ___.","opts":["15 s / 30 s","30 s / 45 s","45 s / 60 s","60 s / 90 s"],"a":2,"why":"It is the last Speaking task (question 11) and has the longest answer time."},{"t":"tf","q":"TOEIC Writing lasts about 20 minutes.","a":false,"why":"TOEIC Writing lasts about 60 minutes. Speaking lasts about 20 minutes. Writing has 8 questions; the opinion essay alone takes 30 minutes."},{"t":"gap","q":"Listening and Reading are each scored ____ to 495, so the total is 10 to ____.","a":["5","990"],"why":"Speaking and Writing are scored separately, 0–200 each."},{"t":"mc","q":"What is the minimum Listening & Reading total for B2?","opts":["550","785","945","990"],"a":1,"why":"B1 = 550, B2 = 785, C1 = 945 (official ETS minimum scores)."},{"t":"tf","q":"A perfect TOEIC Listening & Reading score shows CEFR level C2.","a":false,"why":"TOEIC does not report C2. The highest level is C1. TOEIC is designed for workplace English up to C1."},{"t":"tf","q":"A high Listening & Reading score proves that a candidate can speak and write well.","a":false,"why":"A good L&R score does not prove good speaking or writing. The two tests measure different skills, so their scores are only moderately related."},{"t":"mc","q":"TOEIC Bridge is designed for learners at which levels?","opts":["A1–B1","B1–B2","B2–C1","C1–C2"],"a":0,"why":"TOEIC Bridge is an easier version for beginners and lower-intermediate learners."},{"t":"mc","q":"How long does the TOEIC Reading section last?","opts":["45 minutes","60 minutes","75 minutes","90 minutes"],"a":2,"why":"Reading has 100 questions. Listening lasts about 45 minutes."},{"t":"mc","q":"At IIG Vietnam, how long must candidates wait between two TOEIC tests?","opts":["1 working day","5 working days","30 days","60 days"],"a":1,"why":"60 days is the time limit for IELTS One Skill Retake, not TOEIC."},{"t":"mc","q":"Which exam is designed to measure English for the workplace and international business?","opts":["IELTS Academic","TOEIC","TOEFL iBT","C1 Advanced"],"a":1,"why":"TOEIC is mostly used by employers and by universities as a graduation requirement.","reverse":true},{"t":"mc","q":"Which organisation runs the TOEIC exam in Vietnam?","opts":["IDP","The British Council","REAP JSC","IIG Vietnam"],"a":3,"why":"IIG Vietnam runs TOEIC with MOET approval. REAP JSC runs Linguaskill.","reverse":false},{"t":"mc","q":"What is the score range of the TOEIC Listening & Reading total?","opts":["0 – 9","0 – 200","10 – 990","140 – 210"],"a":2,"why":"Listening and Reading are each scored 5–495. (0–200 = Speaking or Writing; 140–210 = Linguaskill.)","reverse":false},{"t":"mc","q":"Which of the following is NOT one of the tasks in the TOEIC Speaking exam?","opts":["Read a text aloud","Describe a picture","Express an opinion","Write an opinion essay"],"a":3,"why":"The opinion essay is part of TOEIC Writing, not Speaking.","reverse":false},{"t":"mc","q":"Which of the following is the correct full name of TOEIC?","opts":["Test of English for International Communication","Test of English for International Cooperation","Test of English for International Commerce","Test of English as an International Certificate"],"a":0,"why":"TOEFL = Test of English as a Foreign Language.","reverse":false},{"t":"mc","q":"Which of the following statements is TRUE about TOEIC Listening & Reading and TOEIC Speaking & Writing?","opts":["They are two separate tests","They are always taken on the same day","Speaking & Writing is taken on paper","Listening & Reading includes speaking"],"a":0,"why":"Speaking & Writing is a separate test taken on computer.","reverse":false},{"t":"mc","q":"What is the minimum TOEIC Listening & Reading total score for CEFR B2?","opts":["550","785","945","990"],"a":1,"why":"550 = B1; 785 = B2; 945 = C1.","reverse":false},{"t":"mc","q":"Which CEFR level does TOEIC NOT report?","opts":["A1","B1","C1","C2"],"a":3,"why":"TOEIC reports A1 to C1; the highest level is C1 (945).","reverse":false}],"TOEFL iBT":[{"t":"tf","q":"TOEFL and TOEIC are both made by ETS.","a":true,"why":"ETS (Educational Testing Service) in the USA makes both tests."},{"t":"tf","q":"Candidates can still take the TOEFL iBT Paper Edition in 2026.","a":false,"why":"The Paper Edition ended in January 2024. TOEFL iBT is now taken on computer, at a test centre or at home."},{"t":"gap","q":"A new, redesigned TOEFL iBT started on 21 ____ 2026.","a":["January"],"why":"The redesign brought new tasks, adaptive Reading and Listening, and a new 1–6 score scale."},{"t":"mc","q":"TOEFL iBT is accepted by more than how many institutions?","opts":["3,000","8,000","13,000","30,000"],"a":2,"why":"More than 13,000 institutions in over 160 countries."},{"t":"mc","q":"What is the order of sections in the new TOEFL iBT?","opts":["Listening, Reading, Speaking, Writing","Reading, Listening, Writing, Speaking","Speaking, Writing, Reading, Listening","Writing, Speaking, Listening, Reading"],"a":1,"why":"Reading comes first and Speaking comes last."},{"t":"tf","q":"In the new TOEFL iBT, Reading and Listening are adaptive.","a":true,"why":"They are “multistage adaptive”: the second stage is easier or harder depending on how well the candidate did in the first."},{"t":"gap","q":"The new test takes about ____ minutes of testing time (under 2 hours in total).","a":["90"],"why":"The old 2023–2026 test took about 2 hours."},{"t":"mc","q":"Which of these is a new TOEFL iBT Reading task?","opts":["Insert a sentence","Complete the Words","Independent essay","Describe a picture"],"a":1,"why":"The Reading tasks are Complete the Words, Read in Daily Life and Read an Academic Passage."},{"t":"gap","q":"The Speaking section has ____ items and lasts ____ minutes.","a":["11","8"],"why":"Listen and Repeat (7 sentences) + Take an Interview (4 questions)."},{"t":"tf","q":"In “Take an Interview”, candidates get 30 seconds to prepare each answer.","a":false,"why":"There is no preparation time; candidates answer each of the 4 questions for 45 seconds. This task checks how well candidates can speak without planning."},{"t":"mc","q":"What is the score scale of the new TOEFL iBT?","opts":["0–120","1–6","0–9","10–990"],"a":1,"why":"1–6 in half-point steps. 0–120 was the old scale; 0–9 is IELTS; 10–990 is TOEIC."},{"t":"mc","q":"A TOEFL iBT overall score of 4.5 is linked to which CEFR level?","opts":["B1","B2","C1","C2"],"a":1,"why":"3–3.5 = B1, 4–4.5 = B2, 5–5.5 = C1, 6 = C2."},{"t":"tf","q":"Until January 2028, the score report also shows a comparable 0–120 score.","a":true,"why":"This helps universities that still use the old scale during the change."},{"t":"gap","q":"TOEFL iBT results come within ____ hours, and scores are valid for ____ years.","a":["72","2"],"why":"MyBest scores can also combine the best section scores from different test dates."},{"t":"mc","q":"What does “iBT” stand for?","opts":["international Business Test","internet-Based Test","integrated Basic Test","individual Band Test"],"a":1,"why":"TOEFL iBT is the internet-based version, introduced in 2005–2006."},{"t":"mc","q":"Who scores TOEFL iBT Speaking and Writing?","opts":["Human raters only","AI only","AI together with human raters","The candidate’s own teacher"],"a":2,"why":"ETS uses an AI scoring engine, and human raters are still part of the process."},{"t":"mc","q":"Which of these is a TOEFL iBT Writing task?","opts":["Build a Sentence","Describe a picture","Listen and Repeat","Complete the Words"],"a":0,"why":"Listen and Repeat is Speaking; Complete the Words is Reading; Describe a picture is TOEIC."},{"t":"mc","q":"Which TOEFL test is for children aged 8–11?","opts":["TOEFL Junior","TOEFL Primary","TOEFL Essentials","TOEFL ITP"],"a":1,"why":"TOEFL Junior is for learners aged 11 and over."},{"t":"mc","q":"Which organisation develops both TOEFL iBT and TOEIC?","opts":["ETS","The British Council","Cambridge University Press & Assessment","IDP"],"a":0,"why":"ETS (Educational Testing Service) in the USA makes both tests.","reverse":true},{"t":"mc","q":"Which exam has used a 1–6 score scale since 21 January 2026?","opts":["IELTS","TOEIC","TOEFL iBT","Linguaskill"],"a":2,"why":"The overall TOEFL iBT score is the average of the four sections, rounded to the nearest 0.5.","reverse":true},{"t":"mc","q":"What is the order of the sections in the new TOEFL iBT?","opts":["Listening – Reading – Speaking – Writing","Reading – Listening – Writing – Speaking","Speaking – Writing – Reading – Listening","Writing – Speaking – Listening – Reading"],"a":1,"why":"Reading comes first and Speaking comes last.","reverse":false},{"t":"mc","q":"How long are TOEFL iBT scores valid?","opts":["1 year","2 years","3 years","No expiry date"],"a":1,"why":"TOEFL iBT results come within 72 hours and are valid for 2 years.","reverse":false},{"t":"mc","q":"Which exam was created to check the English of international students applying to US universities?","opts":["IELTS","TOEFL","TOEIC","Aptis"],"a":1,"why":"ELTS (the earlier IELTS) was created for UK universities.","reverse":true},{"t":"mc","q":"What does “adaptive” mean in TOEFL iBT Reading and Listening?","opts":["Questions depend on earlier answers","Candidates choose the question order","The test can be taken at home","Each recording is played twice"],"a":0,"why":"They are “multistage adaptive”: the questions become easier or harder.","reverse":false},{"t":"mc","q":"Where can candidates take TOEFL iBT?","opts":["Only at a test centre","At a test centre or at home","Only on paper at a university","Only at the British Council"],"a":1,"why":"The Home Edition lets candidates take the test at home.","reverse":false}],"Aptis General":[{"t":"mc","q":"Which organisation develops Aptis?","opts":["Cambridge University Press & Assessment","The British Council","ETS","IDP"],"a":1,"why":"Aptis is the British Council’s own test. It was launched in August 2012."},{"t":"tf","q":"Aptis was first designed as a test sold to organisations, not to individuals.","a":true,"why":"It was a business-to-business test: flexible, affordable and accessible for testing large groups."},{"t":"gap","q":"Since April 2022, the certificated test for individuals has been called Aptis ____.","a":["ESOL"],"why":"Aptis ESOL is regulated by Ofqual, the exam regulator in England. The format did not change."},{"t":"tf","q":"Organisations can leave out the Core (grammar and vocabulary) component.","a":false,"why":"Organisations can choose the skills, but the Core is always included. The Core score also helps decide borderline cases."},{"t":"mc","q":"How many answer options do Aptis grammar questions have?","opts":["2","3","4","5"],"a":1,"why":"There are 25 grammar questions with 3 options each. Many student slides wrongly show 4 options."},{"t":"mc","q":"What does Reading Part 2 ask candidates to do?","opts":["Match headings to paragraphs","Put sentences in the correct order","Fill gaps with 3 options","Answer True/False questions"],"a":1,"why":"Part 4 is heading matching; Part 1 is gap-filling with 3 options."},{"t":"tf","q":"In Aptis General Listening, each recording is played only once.","a":false,"why":"In Aptis General, every recording can be played up to twice. The candidate chooses whether to listen a second time."},{"t":"tf","q":"The Core score is added to the four skill scores to give a total out of 250.","a":false,"why":"The total is out of 200 (four skills × 50). The Core is not included. The Core gets a score only, with no CEFR level."},{"t":"mc","q":"What is the highest result Aptis General reports?","opts":["B2","“C”","C1","C2"],"a":1,"why":"Aptis General does not separate C1 and C2. Candidates above B2 get a “C” result."},{"t":"mc","q":"What is the minimum age for Aptis ESOL?","opts":["13","15","16","18"],"a":2,"why":"Younger learners can take Aptis for Teens."},{"t":"mc","q":"How long does Aptis General Listening take?","opts":["30 minutes","35 minutes","40 minutes","50 minutes"],"a":2,"why":"Listening has 25 items. Reading takes 35 minutes and Writing 50 minutes."},{"t":"mc","q":"In Listening Part 3, what do candidates decide?","opts":["The speaker’s job","Whether an opinion belongs to the man, the woman or both","The correct order of events","The meaning of a word"],"a":1,"why":"Candidates hear one discussion and match each opinion to the speakers."},{"t":"mc","q":"What happens in Speaking Part 3 of Aptis General?","opts":["Candidates answer 3 personal questions","Candidates describe one photo","Candidates compare two photos","Candidates give a presentation"],"a":2,"why":"Part 1 = personal questions; Part 2 = one photo; Part 4 = one picture and 3 abstract questions."},{"t":"mc","q":"In Aptis, which component is always included, whichever skills an organisation chooses?","opts":["Speaking","Listening","The Core (grammar and vocabulary)","Writing"],"a":2,"why":"Organisations can choose the skills, but the Core is always included.","reverse":false},{"t":"mc","q":"Which exam reports the levels A0, A1, A2, B1, B2 and “C”?","opts":["Aptis General","Aptis Advanced","VSTEP","Linguaskill"],"a":0,"why":"Aptis General does not separate C1 and C2, so it reports “C”.","reverse":true},{"t":"mc","q":"In Aptis General Listening, how many times can each recording be played?","opts":["Once only","Up to twice","Three times","As many times as the candidate likes"],"a":1,"why":"Every recording can be played up to twice; the candidate chooses.","reverse":false},{"t":"mc","q":"Which organisation develops the Aptis exam?","opts":["The British Council","ETS","Cambridge University Press & Assessment","IIG Vietnam"],"a":0,"why":"Aptis was first designed as a business-to-business test, sold to organisations.","reverse":false},{"t":"mc","q":"What is each Aptis skill scored out of?","opts":["9","30","50","200"],"a":2,"why":"The four skills add up to a total out of 200; the Core is not included.","reverse":false},{"t":"mc","q":"When is an overall CEFR level given in Aptis?","opts":["Only when all four skills are taken","Whenever the Core is taken","Always, even for one skill","Only when Speaking is taken"],"a":0,"why":"With fewer skills, each skill gets its own level but there is no overall level.","reverse":false}],"Aptis Advanced":[{"t":"tf","q":"Aptis Advanced covers only levels C1 and C2.","a":false,"why":"Aptis Advanced covers B1 to C2. It is the only Aptis variant that reports C1 and C2 separately."},{"t":"gap","q":"The whole Aptis Advanced test takes ____ minutes; Aptis General takes 162.","a":["170"],"why":"Core 25 + Reading 60 + Listening 30 + Writing 45 + Speaking 10 = 170 minutes."},{"t":"tf","q":"In Aptis Advanced Listening, Parts 3 and 4 are played only once.","a":true,"why":"Parts 1 and 2 can be played up to twice. Parts 3 and 4 are heard once only."},{"t":"mc","q":"How many Writing parts does Aptis Advanced have?","opts":["2","3","4","5"],"a":1,"why":"Social-network replies, a formal email, and a website article. Aptis General has 4 parts."},{"t":"mc","q":"What happens in Speaking Part 3?","opts":["The candidate compares two pictures","The candidate gives a presentation using “for” and “against” points","The candidate answers personal questions","The candidate reads a text aloud"],"a":1,"why":"1 minute to prepare, then 90 seconds to speak. Comparing two pictures is Part 1."},{"t":"tf","q":"In Speaking Part 4, the candidate has 1 minute to prepare.","a":false,"why":"Part 4 is a follow-up question with no preparation time (45 seconds to speak). It checks how well the candidate can speak without planning."},{"t":"gap","q":"To get C2 in a skill, a candidate needs ____ out of 50.","a":["50"],"why":"C2 needs a perfect score. C1 starts at 38 in Listening, 40 in Reading and 44 in Writing and Speaking."},{"t":"tf","q":"The overall CEFR level is given even if the candidate takes only two skills.","a":false,"why":"The overall CEFR level is given only if all four skills are taken. With fewer skills, each skill gets its own level but there is no overall level."},{"t":"mc","q":"How long does Aptis Advanced Reading take?","opts":["35 minutes","45 minutes","60 minutes","75 minutes"],"a":2,"why":"It has 25 items in 4 parts. Aptis General Reading takes 35 minutes."},{"t":"mc","q":"What does Reading Part 4 use?","opts":["One long text","Two short texts on the same topic","Sentences to put in order","A table to complete"],"a":1,"why":"The two texts have 6 gaps, each with 3 options."},{"t":"mc","q":"How long does Aptis Advanced Listening take?","opts":["30 minutes","40 minutes","45 minutes","60 minutes"],"a":0,"why":"It has 25 items in 4 parts. Aptis General Listening takes 40 minutes."},{"t":"mc","q":"What is Writing Part 2?","opts":["An informal email","A formal email to an authority","A website article","An essay"],"a":1,"why":"Part 1 = social-network replies; Part 3 = website article. There is no essay."},{"t":"mc","q":"How long does the Aptis Advanced Speaking test take?","opts":["10 minutes","12 minutes","15 minutes","20 minutes"],"a":0,"why":"Aptis General Speaking takes 12 minutes. Some student slides wrongly say 15."},{"t":"mc","q":"What happens in Speaking Part 1?","opts":["Candidates answer personal questions","Candidates compare two pictures","Candidates give a presentation","Candidates read a text aloud"],"a":1,"why":"They compare the pictures and then answer 2 more questions, 45 seconds each."},{"t":"mc","q":"What do candidates below B1 receive?","opts":["A B1 certificate","A report showing A0–A2","Nothing at all","An Aptis General certificate"],"a":1,"why":"Aptis Advanced certificates cover B1 to C2 only."},{"t":"mc","q":"Which CEFR levels does Aptis Advanced cover?","opts":["A1 – B2","A2 – C1","B1 – C2","B2 – C2"],"a":2,"why":"It is the only Aptis variant that reports C1 and C2 separately.","reverse":false},{"t":"mc","q":"In Aptis Advanced Listening, which parts are played only once?","opts":["Parts 1 and 2","Parts 2 and 3","Parts 3 and 4","All four parts"],"a":2,"why":"Parts 1 and 2 can be played up to twice; Parts 3 and 4 only once.","reverse":false},{"t":"mc","q":"In which part of Aptis Advanced Speaking do candidates give a presentation using “for” and “against” points?","opts":["Part 1","Part 2","Part 3","Part 4"],"a":2,"why":"Part 3: 1 minute to prepare, 90 seconds to speak. Part 1 is comparing two pictures.","reverse":false},{"t":"mc","q":"Which Aptis variant reports C1 and C2 separately?","opts":["Aptis General","Aptis Advanced","Both Aptis General and Aptis Advanced","Neither of them"],"a":1,"why":"Aptis General only reports “C”.","reverse":false},{"t":"mc","q":"What score does a candidate need in an Aptis Advanced skill to get C2?","opts":["40 out of 50","44 out of 50","48 out of 50","50 out of 50"],"a":3,"why":"C2 needs a perfect score. C1 starts at 38 (Listening), 40 (Reading) and 44 (Writing, Speaking).","reverse":false},{"t":"mc","q":"What do Aptis Advanced candidates below B1 receive?","opts":["A B1 certificate","A report showing A0 – A2","An Aptis General certificate","Nothing at all"],"a":1,"why":"Aptis Advanced certificates cover B1 to C2 only.","reverse":false}],"B2 First":[{"t":"tf","q":"B2 First and B2 First for Schools have completely different formats.","a":false,"why":"They have the same format, except for Writing Part 2. B2 First is for adults; B2 First for Schools uses topics for school-age learners."},{"t":"mc","q":"How long is the Reading and Use of English paper?","opts":["1 hour","1 hour 15 minutes","1 hour 30 minutes","1 hour 45 minutes"],"a":1,"why":"7 parts and 52 questions. (C1 Advanced: 1 hour 30 minutes.)"},{"t":"tf","q":"Candidates taking B2 First (the adult version) can choose to write a story in Writing Part 2.","a":false,"why":"A story is only in B2 First for Schools. A report is only in B2 First. This is the only difference between the two versions."},{"t":"tf","q":"Every B2 First Listening recording is heard twice.","a":true,"why":"Listening has 4 parts and 30 questions. IELTS and TOEIC recordings are heard only once."},{"t":"mc","q":"A candidate scores 182 on B2 First. What result does she get?","opts":["A B1 certificate","Grade C (B2)","Grade B (B2)","Grade A and a C1 certificate"],"a":3,"why":"180–190 = Grade A (C1); 160–179 = B2; 140–159 = B1 certificate."},{"t":"tf","q":"The B2 First certificate expires after 2 years.","a":false,"why":"The B2 First certificate does not expire. Universities or visa authorities may still set their own time limits."},{"t":"mc","q":"How many papers does B2 First have?","opts":["3","4","5","7"],"a":1,"why":"There are 4 papers but 5 scores, because Reading and Use of English are scored separately."},{"t":"mc","q":"What is Part 6 of Reading and Use of English?","opts":["Multiple-choice cloze","Word formation","Gapped text with missing sentences","Multiple matching"],"a":2,"why":"Part 1 = multiple-choice cloze; Part 3 = word formation; Part 7 = multiple matching."},{"t":"mc","q":"What is Writing Part 1?","opts":["A compulsory essay","A report","A story","A review"],"a":0,"why":"In Part 2 candidates choose one task, such as an article, email/letter or review."},{"t":"mc","q":"How long is the Speaking test for a pair of candidates?","opts":["11–14 minutes","14 minutes","15 minutes","20 minutes"],"a":1,"why":"20 minutes is for a group of three. (C1 Advanced = 15 minutes; IELTS = 11–14 minutes.)"},{"t":"mc","q":"In the Speaking test, what does the assessor do?","opts":["Asks the questions","Only listens and marks","Talks with the candidates","Records the answers on a computer"],"a":1,"why":"The interlocutor is the examiner who asks the questions."},{"t":"mc","q":"How much is each of the five scores worth?","opts":["10%","20%","25%","40%"],"a":1,"why":"Reading and Use of English together make up 40%, because they are two of the five scores."},{"t":"mc","q":"Which of these is NOT a B2 First Writing criterion?","opts":["Content","Communicative Achievement","Organisation","Pronunciation"],"a":3,"why":"The fourth Writing criterion is Language. Pronunciation is a Speaking criterion."},{"t":"mc","q":"Which Cambridge exam has a “for Schools” version that is different only in Writing Part 2?","opts":["C1 Advanced","B2 First","Linguaskill","Aptis General"],"a":1,"why":"There is no Schools version of C1 Advanced. In B2 First, a report is only for adults and a story only for Schools.","reverse":true},{"t":"mc","q":"In the B2 First Speaking test, which examiner only listens and marks?","opts":["The interlocutor","The assessor","The invigilator","The candidate’s partner"],"a":1,"why":"The interlocutor asks the questions; the assessor only listens and marks.","reverse":false},{"t":"mc","q":"A candidate scores 175 on B2 First. What does she receive?","opts":["A B1 certificate","A B2 certificate","A C1 certificate","No certificate"],"a":1,"why":"140–159 = B1; 160–179 = B2 (Grade C or B); 180–190 = Grade A, C1.","reverse":false},{"t":"mc","q":"What was B2 First called before September 2017?","opts":["First Certificate in English (FCE)","Certificate in Advanced English (CAE)","Certificate of Proficiency in English (CPE)","Cambridge Business English"],"a":0,"why":"FCE was renamed B2 First in September 2017.","reverse":false},{"t":"mc","q":"How many scores does B2 First report, and how much is each one worth?","opts":["4 scores, 25% each","5 scores, 20% each","3 scores, about 33% each","2 scores, 50% each"],"a":1,"why":"Reading, Use of English, Writing, Listening and Speaking – 20% each.","reverse":false},{"t":"mc","q":"How many candidates usually take the B2 First Speaking test together?","opts":["One","Two","Three","Four"],"a":1,"why":"Speaking takes 14 minutes for a pair of candidates, with two examiners.","reverse":false}],"C1 Advanced":[{"t":"tf","q":"CAE was created to fill the gap between FCE and CPE.","a":true,"why":"FCE is B2 level and CPE (now C2 Proficiency) is C2 level, so CAE filled the C1 level."},{"t":"tf","q":"There is a C1 Advanced for Schools version.","a":false,"why":"There is no Schools version of C1 Advanced. B2 First does have a Schools version."},{"t":"mc","q":"How is the C1 Advanced Reading and Use of English paper organised?","opts":["7 parts, 52 questions","8 parts, 56 questions","4 parts, 40 questions","3 passages, 40 questions"],"a":1,"why":"It takes 1 hour 30 minutes. B2 First has 7 parts and 52 questions."},{"t":"mc","q":"Which genre appears in C1 Advanced Writing Part 2 but NOT in B2 First?","opts":["Review","Email","Proposal","Story"],"a":2,"why":"C1 Advanced Part 2 options: letter/email, proposal, report or review."},{"t":"tf","q":"In C1 Advanced Listening, Part 1 and Part 3 both have 4 answer options.","a":false,"why":"Part 1 has 3 options; Part 3 has 4 options. This difference is often confused, even in student presentations."},{"t":"mc","q":"What happens in C1 Advanced Speaking Part 2?","opts":["Candidates compare 2 photos","Candidates get 3 photos and talk about 2","Candidates describe 1 photo","Candidates read a text aloud"],"a":1,"why":"In B2 First, candidates get 2 photos."},{"t":"gap","q":"A score of ____ to 210 gives Grade A and a C2 certificate.","a":["200"],"why":"180–199 = C1 certificate; 160–179 = B2 certificate."},{"t":"mc","q":"About how long does C1 Advanced take in total?","opts":["2 hours 45 minutes","3.5 hours","3 hours 55 minutes","4 hours 30 minutes"],"a":2,"why":"B2 First takes about 3.5 hours; IELTS takes 2 hours 45 minutes."},{"t":"mc","q":"What do candidates do in Writing Part 1?","opts":["Describe a graph","Write a compulsory essay, choosing 2 of 3 points","Write a story","Write a formal letter"],"a":1,"why":"They say which point is more important and give reasons."},{"t":"mc","q":"Which country currently accepts only the paper-based C1 Advanced for visas?","opts":["The UK","Australia","Canada","The USA"],"a":1,"why":"C1 Advanced is not a UK visa test."},{"t":"mc","q":"C1 Advanced is accepted by more than how many organisations?","opts":["1,000","5,000","11,000","13,500"],"a":2,"why":"13,500+ is the figure for IELTS."},{"t":"mc","q":"Which exam was created to fill the gap between FCE and CPE?","opts":["IELTS","B2 First","C1 Advanced","Linguaskill"],"a":2,"why":"FCE is B2 level and CPE is C2 level, so CAE (now C1 Advanced) filled the C1 level.","reverse":true},{"t":"mc","q":"Which Writing Part 2 task can candidates choose in C1 Advanced but NOT in B2 First?","opts":["Proposal","Email","Review","Article"],"a":0,"why":"C1 Advanced Part 2 options: letter/email, proposal, report or review.","reverse":false},{"t":"mc","q":"In which exam’s Speaking Part 2 does each candidate get 3 photos and talk about 2 of them?","opts":["B2 First","C1 Advanced","Aptis General","IELTS"],"a":1,"why":"In B2 First, each candidate compares 2 photos.","reverse":true},{"t":"mc","q":"Which name is still printed on the C1 Advanced certificate?","opts":["Certificate in Advanced English","Cambridge English: Academic","Certificate in Academic English","Advanced Proficiency Certificate"],"a":0,"why":"CAE (Certificate in Advanced English) was renamed C1 Advanced in 2017, but the certificate keeps the old name.","reverse":false},{"t":"mc","q":"Which of the following statements is TRUE about C1 Advanced Listening?","opts":["Every part is heard twice","Every part is heard only once","Only Part 4 is heard twice","Candidates choose how often to listen"],"a":0,"why":"IELTS, TOEIC and VSTEP recordings are heard only once.","reverse":false},{"t":"mc","q":"A candidate scores 205 on C1 Advanced. What does she receive?","opts":["A B2 certificate","A C1 certificate","Grade A and a C2 certificate","No certificate"],"a":2,"why":"160–179 = B2; 180–199 = C1; 200–210 = Grade A, C2.","reverse":false}],"VSTEP":[{"t":"mc","q":"What does VSTEP stand for?","opts":["Vietnamese Standard Test of English Performance","Vietnamese Standardized Test of English Proficiency","Vietnam Standard Test for English Placement","Vietnamese System Test of English Proficiency"],"a":1,"why":"The main version is VSTEP.3-5, which covers Levels 3–5 of Vietnam’s 6-level framework."},{"t":"mc","q":"Who developed VSTEP?","opts":["The British Council","ULIS, Vietnam National University, Hanoi","Cambridge University Press & Assessment","IIG Vietnam"],"a":1,"why":"ULIS developed it under the National Foreign Languages Project."},{"t":"tf","q":"Master’s applicants need at least Level 3 (B1).","a":true,"why":"VSTEP is also used for university graduation, teachers, lecturers and public-sector staff."},{"t":"tf","q":"VSTEP.3-5 is three separate exams: one for B1, one for B2 and one for C1.","a":false,"why":"VSTEP.3-5 is one exam. The candidate’s score decides whether they get Level 3, 4 or 5. Candidates do not choose a level before the test."},{"t":"gap","q":"VSTEP Listening has ____ multiple-choice questions, and each recording is heard ____.","a":["35","once"],"why":"Three parts: 8, 12 and 15 questions."},{"t":"tf","q":"VSTEP Reading includes gap-fill and matching tasks.","a":false,"why":"VSTEP Reading has 4 passages with 10 multiple-choice questions each (40 questions). All Reading questions are multiple choice."},{"t":"mc","q":"Writing Task 2 (the essay) counts for how much of the Writing score?","opts":["One-third","Half","Two-thirds","All of it"],"a":2,"why":"The essay is at least 250 words and takes about 40 minutes."},{"t":"mc","q":"Which of these is NOT a part of VSTEP Speaking?","opts":["Social interaction","Solution discussion","Picture description","Topic development"],"a":2,"why":"VSTEP Speaking has no picture task. Part 3 uses a mind map."},{"t":"mc","q":"A candidate’s overall score is 6.0. What result does she get?","opts":["Level 3 (B1)","Level 4 (B2)","Level 5 (C1)","No level"],"a":1,"why":"4.0–5.5 = Level 3 (B1); 6.0–8.0 = Level 4 (B2); 8.5–10 = Level 5 (C1)."},{"t":"gap","q":"An overall score of ____ to 10 gives Level 5 (C1).","a":["8.5"],"why":"Each skill is scored 0–10, and the overall score is their average, rounded to 0.5."},{"t":"tf","q":"A candidate with an overall score of 3.5 receives Level 2 (A2).","a":false,"why":"Below 4.0, no level is awarded. Level 2 (A2) is a separate test. VSTEP.3-5 only awards B1, B2 or C1."},{"t":"tf","q":"A VSTEP certificate expires after 2 years.","a":false,"why":"There is no national expiry date. The organisation that receives the certificate decides. This rule is in Circular 09/2026, Article 3(3)."},{"t":"mc","q":"How many institutions were licensed to run VSTEP in March 2025?","opts":["8","18","38","80"],"a":2,"why":"They include ULIS-VNU, Hanoi University, Hue University of Foreign Languages and Can Tho University."},{"t":"mc","q":"Which document set up Vietnam’s 6-level foreign language framework?","opts":["Decision 729/QĐ-BGDĐT (2015)","Circular 01/2014/TT-BGDĐT","Circular 09/2026/TT-BGDĐT","Circular 24/2024/TT-BGDĐT"],"a":1,"why":"Decision 729 set the VSTEP.3-5 format; Circular 09/2026 sets the rules for test organisers."},{"t":"mc","q":"About how long does VSTEP.3-5 take?","opts":["120 minutes","150 minutes","172 minutes","200 minutes"],"a":2,"why":"Listening about 40 + Reading 60 + Writing 60 + Speaking 12 minutes."},{"t":"mc","q":"How long is the VSTEP Speaking test?","opts":["8 minutes","11–14 minutes","12 minutes","16 minutes"],"a":2,"why":"It has 3 parts. (IELTS = 11–14 minutes; Linguaskill = 16 minutes; TOEFL iBT = 8 minutes.)"},{"t":"mc","q":"Which of these is NOT a VSTEP Speaking criterion?","opts":["Grammar","Pronunciation","Discourse","Interactive Communication"],"a":3,"why":"VSTEP criteria: grammar, vocabulary, pronunciation, fluency and discourse. Interactive Communication is a Cambridge criterion."},{"t":"mc","q":"Which exam was developed by ULIS, Vietnam National University, Hanoi, under the National Foreign Languages Project?","opts":["Aptis","VSTEP","Linguaskill","TOEIC"],"a":1,"why":"VSTEP was created to give Vietnam its own standard test at a lower cost.","reverse":true},{"t":"mc","q":"What level does an overall VSTEP score of 6.0 – 8.0 give?","opts":["Level 3 (B1)","Level 4 (B2)","Level 5 (C1)","No level"],"a":1,"why":"4.0–5.5 = Level 3 (B1); 6.0–8.0 = Level 4 (B2); 8.5–10 = Level 5 (C1).","reverse":false},{"t":"mc","q":"Which of the following statements is TRUE about the VSTEP exam?","opts":["It is recognised mainly in Vietnam","Candidates choose B1, B2 or C1 before the test","Its Speaking test includes a picture-description task","Its certificate always expires after 2 years"],"a":0,"why":"One exam gives Levels 3–5; there is no picture task; there is no national expiry date.","reverse":false},{"t":"mc","q":"Which CEFR levels can VSTEP.3-5 award?","opts":["A1 – C2","A2 – B2","B1 – C1","B2 – C2"],"a":2,"why":"Level 3 = B1, Level 4 = B2, Level 5 = C1. It does not award A1, A2 or C2.","reverse":false},{"t":"mc","q":"Which exam has Speaking parts called social interaction, solution discussion and topic development?","opts":["IELTS","VSTEP","Aptis General","Linguaskill"],"a":1,"why":"Part 3 (topic development) uses a mind map.","reverse":true},{"t":"mc","q":"Who decides how long a VSTEP certificate is accepted?","opts":["MOET – always 2 years","ULIS – always 1 year","The organisation receiving it","The test centre where it was taken"],"a":2,"why":"There is no national expiry date.","reverse":false}],"Linguaskill":[{"t":"mc","q":"Who makes Linguaskill?","opts":["The British Council","ETS","Cambridge University Press & Assessment","IDP"],"a":2,"why":"Cambridge also makes B2 First and C1 Advanced."},{"t":"tf","q":"Linguaskill Business replaced the BEC exams.","a":true,"why":"The BEC exams (Business English Certificates) ended in 2024."},{"t":"mc","q":"Who mainly uses Linguaskill?","opts":["Immigration offices","Organisations such as universities and employers","Primary schools","Only UK universities"],"a":1,"why":"It is used for admission, graduation and recruitment."},{"t":"tf","q":"Candidates must take all four Linguaskill modules on the same day.","a":false,"why":"Each module can be taken separately. Organisations choose only the skills they need."},{"t":"gap","q":"Reading and Listening are ____ tests: the questions get easier or harder depending on earlier answers.","a":["adaptive"],"why":"TOEFL iBT Reading and Listening are also adaptive since 2026."},{"t":"mc","q":"About how long do Reading and Listening each take?","opts":["20 minutes","40 minutes","60 minutes","75 minutes"],"a":1,"why":"About 40 minutes each, with a maximum of 59 minutes."},{"t":"gap","q":"Since 8 October 2025, the Writing module lasts ____ minutes and has ____ parts.","a":["55","2"],"why":"Part 1 is an email; Part 2 is an essay (or a report in Linguaskill Business)."},{"t":"mc","q":"How much is Writing Part 2 worth?","opts":["25%","50%","75%","100%"],"a":2,"why":"Part 2 is at least 250 words. Part 1 (the email, at least 50 words) is worth 25%."},{"t":"mc","q":"Which of these is NOT a Linguaskill Speaking task?","opts":["Giving a short presentation","Summarising an audio recording","Discussing a topic with another candidate","Making a recommendation"],"a":2,"why":"Speaking is recorded on a computer, so there is no partner. Paired speaking belongs to B2 First and C1 Advanced."},{"t":"tf","q":"Linguaskill Writing and Speaking are marked only by computer.","a":false,"why":"They are marked by computer and human examiners together (hybrid marking). Automatic marking is checked and supported by trained examiners."},{"t":"mc","q":"A candidate scores 172 on Linguaskill. What is her CEFR level?","opts":["B1","B2","C1","C2"],"a":1,"why":"140–159 = B1; 160–179 = B2; 180–199 = C1; 200–210 = C2."},{"t":"tf","q":"A Linguaskill score of 125 is reported as A2.","a":false,"why":"Scores below 140 are shown as “Not reported”. The new scale reports only B1 to C2. The old 82–180+ scale is no longer used."},{"t":"gap","q":"Linguaskill results come from ____ working days after the test.","a":["3"],"why":"Test centre: about 3–5 days; remote test: about 6–8 days."},{"t":"tf","q":"The Linguaskill certificate expires after 2 years.","a":false,"why":"The digital certificate has no expiry date. Each organisation decides how recent a result must be. My Best Score shows the best result from retakes within 6 months."},{"t":"mc","q":"Which organisation runs Linguaskill in Vietnam with MOET approval?","opts":["IIG Vietnam","REAP JSC","IDP","ULIS – VNU Hanoi"],"a":1,"why":"IIG Vietnam runs TOEIC; IDP runs IELTS; ULIS developed VSTEP."},{"t":"mc","q":"How can candidates take Linguaskill?","opts":["Only on paper","At a test centre or remotely with AI proctoring","At home with no supervision","Only by telephone"],"a":1,"why":"Remote tests are supervised with AI proctoring."},{"t":"mc","q":"What does “My Best Score” do?","opts":["Shows the best result from retakes within 6 months","Adds all module scores together","Removes the lowest module score","Gives one free retake"],"a":0,"why":"Candidates can retake a module within 6 months, and the best result is shown."},{"t":"mc","q":"Which exam has four modules that can each be taken separately, with adaptive Reading and Listening?","opts":["IELTS","VSTEP","Linguaskill","B2 First"],"a":2,"why":"Linguaskill Reading and Listening get easier or harder depending on earlier answers.","reverse":true},{"t":"mc","q":"What CEFR level does a Linguaskill score of 185 equal?","opts":["B1","B2","C1","C2"],"a":2,"why":"140–159 = B1; 160–179 = B2; 180–199 = C1; 200–210 = C2.","reverse":false},{"t":"mc","q":"How are Linguaskill Writing and Speaking marked?","opts":["By computer only","By human examiners only","By computer and human examiners together","By the candidate’s own teacher"],"a":2,"why":"This is called hybrid marking.","reverse":false},{"t":"mc","q":"Which exam reports scores from 140 to 210 and shows scores below 140 as “Not reported”?","opts":["B2 First","C1 Advanced","Linguaskill","Aptis Advanced"],"a":2,"why":"The new Linguaskill scale reports B1 to C2.","reverse":true},{"t":"mc","q":"Which of the following statements is TRUE about Linguaskill Speaking?","opts":["It is face to face with two examiners","It is recorded on a computer","It is taken in pairs","It is marked by the candidate’s teacher"],"a":1,"why":"Answers are recorded and marked by computer and human examiners together.","reverse":false},{"t":"mc","q":"What does “My Best Score” in Linguaskill show?","opts":["The best result from retakes in 6 months","The total of all module scores","The result without the lowest module","The average of all past tests"],"a":0,"why":"Candidates can retake a module within 6 months, and the best result is shown.","reverse":false}]};
window.READING = [{"id":"timekeeper","title":"Timekeeper: Invention of Marine Chronometer","source":"Test 3 – Passage 1","paras":[{"label":"A","text":"Up to the middle of the 18th century, the navigators were still unable to exactly identify the position at sea, so they might face a great number of risks such as the shipwreck or running out of supplies before arriving at the destination. Knowing one’s position on the earth requires two simple but essential coordinates, one of which is the longitude."},{"label":"B","text":"The longitude is a term that can be used to measure the distance that one has covered from one’s home to another place around the world without the limitations of naturally occurring baseline like the equator. To determine longitude, navigators had no choice but to measure the angle with the naval sextant between Moon centre and a specific star—lunar distance—along with the height of both heavenly bodies. Together with the nautical almanac, Greenwich Mean Time (GMT) was determined, which could be adopted to calculate longitude because one hour in GMT means 15-degree longitude. Unfortunately, this approach laid great reliance on the weather conditions, which brought great inconvenience to the crew members. Therefore, another method was proposed, that is, the time difference between the home time and the local time served for the measurement. Theoretically, knowing the longitude position was quite simple, even for the people in the middle of the sea with no land in sight. The key element for calculating the distance travelled was to know, at the very moment, the accurate home time. But the greatest problem is: how can a sailor know the home time at sea?"},{"label":"C","text":"The simple and again obvious answer is that one takes an accurate clock with him, which he sets to the home time before leaving. A comparison with the local time (easily identified by checking the position of the Sun) would indicate the time difference between the home time and the local time, and thus the distance from home was obtained. The truth was that nobody in the 18th century had ever managed to create a clock that could endure the violent shaking of a ship and the fluctuating temperature while still maintaining the accuracy of time for navigation."},{"label":"D","text":"After 1714, as an attempt to find a solution to the problem, the British government offered a tremendous amount of £20,000, which were to be managed by the magnificently named ‘Board of Longitude’. If timekeeper was the answer (and there could be other proposed solutions, since the money wasn’t only offered for timekeeper), then the error of the required timekeeping for achieving this goal needed to be within 2.8 seconds a day, which was considered impossible for any clock or watch at sea, even when they were in their finest conditions."},{"label":"E","text":"This award, worth about £2 million today, inspired the self-taught Yorkshire carpenter John Harrison to attempt a design for a practical marine clock. In the later stage of his early career, he worked alongside his younger brother James. The first big project of theirs was to build a turret clock for the stables at Brockelsby Park, which was revolutionary because it required no lubrication. Harrison designed a marine clock in 1730, and he travelled to London in seek of financial aid. He explained his ideas to Edmond Halley, the Astronomer Royal, who then introduced him to George Graham, Britain’s first-class clockmaker. Graham provided him with financial aid for his early-stage work on sea clocks. It took Harrison five years to build Harrison Number One or H1. Later, he sought the improvement from alternate design and produced H4 with the giant clock appearance. Remarkable as it was, the Board of Longitude wouldn’t grant him the prize for some time until it was adequately satisfied."},{"label":"F","text":"Harrison had a principal contestant for the tempting prize at that time, an English mathematician called John Hadley, who developed sextant. The sextant is the tool that people adopt to measure angles, such as the one between the Sun and the horizon, for a calculation of the location of ships or planes. In addition, his invention is significant since it can help determine longitude."},{"label":"G","text":"Most chronometer forerunners of that particular generation were English, but that doesn’t mean every achievement was made by them. One wonderful figure in the history is the Lancastrian Thomas Earnshaw, who created the ultimate form of chronometer escapement—the spring detent escapement—and made the final decision on format and productions system for the marine chronometer, which turns it into a genuine modern commercial product, as well as a safe and pragmatic way of navigation at sea over the next century and half."}],"groups":[{"intro":"Questions 1–5. Which paragraph (A–G) contains the following information? You may use any letter more than once.","type":"letter","opts":["A","B","C","D","E","F","G"],"items":[["a description of Harrison’s background","E"],["problems caused by poor ocean navigation","A"],["the person who gave financial support to Harrison","E"],["an analysis of the long-term importance of sea clock invention","G"],["the practical usage of longitude","B"]]},{"intro":"Questions 6–8. Do the statements agree with the information in the passage? TRUE / FALSE / NOT GIVEN","type":"tfng","items":[["In theory, sailors can easily calculate their longitude position at sea.","TRUE"],["To determine longitude, the measurement of the distance from the Moon to the given star is a must.","FALSE"],["Greenwich Mean Time was set up by the English navigators.","NOT GIVEN"]]},{"intro":"Questions 9–14. Complete the sentences. Write NO MORE THAN TWO WORDS AND/OR A NUMBER from the passage.","type":"gap","items":[["Sailors were able to use the position of the Sun to calculate ____.",["local time","the local time"]],["An invention that could win the competition would lose no more than ____ every day.",["2.8 seconds","2.8 second","2.8 secs"]],["John and James Harrison’s clock worked accurately without ____.",["lubrication"]],["Harrison’s main competitor’s invention was known as ____.",["sextant","a sextant","the sextant"]],["Hadley’s instrument can use ____ to make a calculation of location of ships or planes.",["angles"]],["The modern version of Harrison’s invention is called ____.",["marine chronometer","the marine chronometer","a marine chronometer"]]]}]},{"id":"crocodile","title":"The Evolutionary Mystery: Crocodile Survives","source":"Test 3 – Passage 2","paras":[{"label":"A","text":"Even though crocodiles have existed for 200 million years, they’re anything but primitive. As crocodiles’ ancestors, crocodilia came to adapt to an aquatic lifestyle. When most of the other contemporary reptiles went extinct, crocodiles were able to make it because their bodies changed and they adapted better to the climate. They witnessed the rise and fall of the dinosaurs, which once ruled the planet, and even the 65 million years of alleged mammalian dominance didn’t wipe them off. Nowadays, the crocodiles and alligators are not that different from their prehistoric ancestors, which proves that they were (and still are) incredibly adaptive."},{"label":"B","text":"The first crocodile-like ancestors came into existence approximately 230 million years ago, and they had many of the features which make crocodiles natural and perfect stealth hunters: streamlined body, long tail, protective armour and long jaws. They are born with four short, webbed legs, but this does not mean that their capacity to move on the ground shall ever be underestimated. When they move, they are so fast that you won’t even have any chance to try making the same mistake again by getting too close, especially when they’re hunting."},{"label":"C","text":"Like other reptiles, crocodiles are poikilothermal animals (commonly known as cold-blooded, whose body temperature changes with that of the surroundings) and consequently, require exposure to sunlight regularly to raise body temperature. When it is too hot, they would rather stay in water or shade. Compared with mammals and birds, crocodiles have a slower metabolism, which makes them less vulnerable to food shortage. In the most extreme case, a crocodile can slow its metabolism down even further, to the point that it would survive without food for a whole year, enabling them to outlive mammals in relatively volatile environments."},{"label":"D","text":"Crocodiles have a highly efficient way to prey catching. The prey rarely realises there might be a crocodile under the water because the crocodile makes a move without any noise or great vibration when spotting its prey. It only keeps its eyes above the water level. As soon as it feels close enough to the victim, it jerks out of the water with its wide open jaws. Crocodiles are successful because they are capable of switching feeding methods. It chases after fish and snatches birds at the water surface, hides in the waterside bushes in anticipation of a gazelle, and when the chance to ambush presents itself, the crocodile dashes forward, knocks the animal out with its powerful tail and then drags the prey into the water to drown."},{"label":"E","text":"In many crocodilian habitats, the hot season brings drought that dries up their hunting grounds, leaving it harder for them to regulate body temperatures. This actually allowed reptiles to rule. For instance, many crocodiles can protect themselves by digging holes and covering themselves in mud, waiting for months without consuming any food or water until the rains finally return. They transform into a quiescent state called aestivation."},{"label":"F","text":"The majority of crocodilian is considered to go into aestivation during the dry season. In a six-year study by Kennett and Christian, the King Crocodiles, a species of Australian freshwater crocodiles, spent nearly four months a year underground without access to water resources. Doubly labelled water was applied to detect field metabolic rates and water flux, and during some years, plasma fluid samples were taken once a month to keep track of the effects of aestivation regarding the accumulation of nitrogenous wastes and electrolyte concentrations."},{"label":"G","text":"The study discovered that the crocodiles’ metabolic engines function slowly, creating waste and exhausting water and fat reserves. Waste is stored in the urine, becoming more and more concentrated. Nevertheless, the concentration of waste products in blood doesn’t fluctuate much, allowing the crocodiles to carry on their normal functions. Besides, even though the crocodiles lost water reserves and body weight when underground, the losses were proportional; upon emerging, the aestivating animals had no dehydration and displayed no other harmful effects such as a slowed-down growth rate. The two researchers reckon that this capacity of crocodiles to get themselves through the harsh times and the long starvation periods is sure to be the answer to the crocodilian line’s survival throughout history."}],"groups":[{"intro":"Questions 15–21. Choose the correct heading for each paragraph (A–G). List of headings: i The favourable feature in the impact of a drought · ii A unique finding that was recently achieved · iii Slow metabolism which makes crocodile a unique reptile · iv The perfectly designed body for a great land roamer · v Shifting eating habits and food intake · vi A project on a special mechanism · vii Regulating body temperature by the surrounding environment · viii Underwater aid in body structure offered to a successful predator · ix A historical story for the supreme survivors · x What makes the crocodile the fastest running animal on land · xi The competition between the crocodiles and other animals","type":"letter","opts":["i","ii","iii","iv","v","vi","vii","viii","ix","x","xi"],"items":[["Paragraph A","ix"],["Paragraph B","iv"],["Paragraph C","iii"],["Paragraph D","v"],["Paragraph E","i"],["Paragraph F","vi"],["Paragraph G","ii"]]},{"intro":"Questions 22–27. Complete the summary “Aestivation”. Write NO MORE THAN TWO WORDS from the passage.","type":"gap","items":[["In many places inhabited by crocodilians, most types of crocodiles have evolved a successful scheme to survive in the drought brought by a ____.",["hot season","dry season"]],["According to Kennett and Christian’s six-year study of Australian freshwater crocodiles, aestivating crocodiles spent around ____ of the year …",["four months","4 months"]],["… and had no access to ____.",["water resources"]],["The amount of water in the body declined proportionately with ____ …",["body weight"]],["… thus there is no sign of ____ and other health-damaging impact on the crocodiles even after an aestivation period.",["dehydration"]],["This super capacity helps crocodiles endure the tough drought without slowing their speed of ____.",["growth"]]]}]},{"id":"innovation","title":"Company Innovation","source":"Test 3 – Passage 3","paras":[{"label":"A","text":"In a shabby office in downtown Manhattan, a group of 30 AI (artificial intelligence) programmers from Umagic are attempting to mimic the brains of a famous sexologist, a celebrated dietitian, a popular fitness coach and a bunch of other specialists. Umagic Systems is an up-and-coming firm, which sets up websites that enable their clients to seek advice from the virtual versions of those figures. The users put in all the information regarding themselves and their objectives; then it’s Umagic’s job to give advice that a star expert would give. Even though the neuroses of American consumers have always been a marketing focus, the future of Umagic is difficult to predict (who knows what it’ll be like in ten years? Asking a computer about your sex life might be either normal or crazy). However, companies such as Umagic are starting to intimidate major American firms, because these young companies regard the half-crazy ‘creative’ ideas as the portal to their triumph in the future."},{"label":"B","text":"Innovation has established itself as the catchword of American business management. Enterprises have realised that they are running out of things that can be outsourced or re-engineered (worryingly, by their competitors too). Winners of today’s American business tend to be companies with innovative powers such as Dell, Amazon and Wal-Mart, which have come up with concepts or goods that have reshaped their industries."},{"label":"C","text":"According to a new book by two consultants from Arthur D. Little, during the last 15 years, the top 20% of firms in <i>Fortune</i> magazine’s annual innovation survey have attained twice as much the shareholder returns as their peers. The desperate search for new ideas is the hormone for a large part of today’s merger boom. The same goes for the money spent on licensing and purchasing others’ intellectual property. Based on the statistics from Pasadena-based Patent & Licence Exchange, trade volume in intangible assets in America has gone up from $15 billion in 1990 to $100 billion in 1998, with small firms and individuals taking up an increasing share of the rewards."},{"label":"D","text":"And that terrifies big companies: it appears that innovation works incompatible with them. Some major famous companies that are always known for ‘innovative ideas’, such as 3M, Procter & Gamble and Rubbermaid, have recently had dry spells. Peter Chernin, who runs the Fox TV and film empire for News Corporation, points out that ‘In the management of creativity, size is your enemy.’ It’s impossible for someone who’s managing 20 movies to be as involved as someone doing 5. Therefore, he has tried to divide the studio into smaller parts, disregarding the risk of higher expenses."},{"label":"E","text":"Nowadays, ideas are more likely to prosper outside big companies. In the old days, when a brilliant scientist came up with an idea and wanted to make money out of it, he would take it to a big company first. But now, with all these cheap venture capital around, he would probably want to commercialise it by himself. So far, Umagic has already raised $5m and is on its way to another $25m. Even in the case of capital-intensive businesses like pharmaceuticals, entrepreneurs have the option to conduct early-stage research and sell out to the big firms when they’re faced with costly, risky clinical trials. Approximately 1/3 of drug firms’ total revenue is now from licensed-in technology."},{"label":"F","text":"Some of the major enterprises such as General Electric and Cisco have been impressively triumphant when it comes to snatching and incorporating small companies’ scores. However, other giants are concerned about the money they have to spend and the way to keep those geniuses who generated the ideas. It is the dream of everyone to develop more ideas within their organisations. Procter & Gamble is currently switching their entire business focus from countries to products; one of the goals is to get the whole company to accept the innovations. In other places, the craving for innovation has caused a frenzy for ‘intrapreneurship’—transferring power and establishing internal idea-workshops and tracking inventory so that the talents will stay."},{"label":"G","text":"Some people don’t believe that this kind of restructuring is sufficient. Clayton Christensen argues in a new book that big firms’ many advantages, such as taking care of their existing customers, can get in the way of innovative behaviour that is necessary for handling disruptive technologies. That’s why there’s been the trend of cannibalisation, which brings about businesses that will confront and jeopardise the existing ones. For example, Bank One has set up Wingspan, which is an online bank that in fact compete with its actual branches."},{"label":"H","text":"There’s no denying that innovation is a big deal. However, do major firms have to be this pessimistic? According to a recent survey of the top 50 innovations in America by <i>Industry Week</i>, ideas are equally likely to come from both big and small companies. Big companies can adopt new ideas when they are mature enough and the risks and rewards have become more quantifiable."},{"label":"I","text":"Can all the creative destruction, cannibalisation and culture tweaking render the big firms more innovative? David Post, the founder of Umagic, cast doubt on this issue, ‘The only successful intrapreneurs are ones who leave and become entrepreneurs.’ He also recalls with glee the look of incomprehension when he tried to convince the idea lab of a big corporation such as IBM of his ‘virtual experts’ idea three years ago—though, he delightfully adds, ‘of course, they could have been right. Innovation, unlike sex, parenting, or fitness, is one area where a computer cannot tell people what to do.’"}],"groups":[{"intro":"Questions 28–33. Which paragraph (A–I) contains the following information? You may use any letter more than once.","type":"letter","opts":["A","B","C","D","E","F","G","H","I"],"items":[["an approach to retain the best employees","F"],["safeguarding expenses on innovative ideas","C"],["a certain counter-effect produced by integrating outside firms","G"],["an example of three famous American companies’ innovation","B"],["an example of one company changing its focus","F"],["an example of a company resolving financial difficulties itself","E"]]},{"intro":"Questions 34–37. Do the statements agree with the information in the passage? TRUE / FALSE / NOT GIVEN","type":"tfng","items":[["Umagic is the most successful innovative company in this new field.","FALSE"],["Amazon and Wal-Mart exchanged their innovation experience.","NOT GIVEN"],["New ideas’ holders had already been known to take it to small companies in the past.","FALSE"],["IBM failed to understand Umagic’s proposal of a new idea.","TRUE"]]},{"intro":"Questions 38–40. Choose the correct letter, A, B, C or D.","type":"mc","items":[["What is the author’s opinion on innovation in paragraph C?",["It only works for big companies.","Fortune magazine has a globally huge influence.","It is becoming increasingly important.","Its effects on American companies are more evident."],"C"],["What is Peter Chernin’s point of view on innovation?",["Small companies are more innovative than big ones.","Film industry needs more innovation than other industries.","We need to cut the cost when risks occur.","New ideas are more likely going to big companies."],"A"],["What is the author’s opinion on innovation at the end of this passage?",["Umagic success lies on the accidental ‘virtual expert’.","Innovation is easy and straightforward.","IBM sets a good example on innovation.","The author’s attitude is uncertain on innovation."],"D"]]}]},{"id":"education","title":"Education Philosophy","source":"Test 4 – Passage 1","paras":[{"label":"A","text":"Although we lack accurate statistics about child mortality in the pre-industrial period, we do have evidence that in the 1660s, the mortality rate for children who died within 14 days of birth was as much as 30 per cent. Nearly all families suffered some premature death. Since all parents expected to bury some of their children, they found it difficult to invest in their newborn children. Moreover, to protect themselves from the emotional consequences of children’s death, parents avoided making any emotional commitment to an infant. It is no wonder that we find mothers leave their babies in gutters or refer to the death in the same paragraph with reference to pickles."},{"label":"B","text":"The 18th century witnessed the transformation from an agrarian economy to an industrial one, one of the vital social changes taking place in the Western world. An increasing number of people moved from their villages and small towns to big cities where life was quite different. Social supports which had previously existed in smaller communities were replaced by ruthless problems such as poverty, crime, substandard housing and disease. Due to the need for additional income to support the family, young children from the poorest families were forced into early employment and thus their childhood became painfully short. Children as young as 7 might be required to work full-time, subjected to unpleasant and unhealthy circumstances, from factories to prostitution. Although such a role has disappeared in most wealthy countries, the practice of childhood employment still remains a staple in underdeveloped countries and rarely disappeared entirely."},{"label":"C","text":"The lives of children underwent a drastic change during the 1800s in the United States. Previously, children from both rural and urban families were expected to participate in everyday labour due to the bulk of manual hard working. Nevertheless, thanks to the technological advances of the mid-1800s, coupled with the rise of the middle class and redefinition of roles of family members, work and home became less synonymous over time. People began to purchase toys and books for their children. When the country depended more upon machines, children in rural and urban areas were less likely to be required to work at home. Beginning from the Industrial Revolution and rising slowly over the course of the 19th century, this trend increased exponentially after civil war. John Locke, one of the most influential writers of his period, created the first clear and comprehensive statement of the ‘environmental position’ that family education determines a child’s life, and via this, he became the father of modern learning theory. During the colonial period, his teachings about child care gained a lot of recognition in America."},{"label":"D","text":"According to Jean Jacques Rousseau, who lived in an era of the American and French Revolution, people were ‘noble savages’ in the original state of nature, meaning they are innocent, free and uncorrupted. In 1762, Rousseau wrote a famous novel <i>Emile</i> to convey his educational philosophy through a story of a boy’s education from infancy to adulthood. This work was based on his extensive observation of children and adolescents, their individuality, his developmental theory and on the memories of his own childhood. He contrasts children with adults and describes their age-specific characteristics in terms of historical perspective and developmental psychology. Johan Heinrich Pestalozzi, living during the early stages of the Industrial Revolution, sought to develop schools to nurture children’s all-round development. He agreed with Rousseau that humans are naturally good but were spoiled by a corrupt society. His approach to teaching consists of the general and special methods, and his theory was based upon establishing an emotionally healthy homelike learning environment, which had to be in place before more specific instructions occurred."},{"label":"E","text":"One of the best-documented cases of Pestalozzi’s theory concerned a so-called feral child named Victor, who was captured in a small town in the south of France in 1800. Prepubescent, mute, naked, and perhaps 11 or 12 years old, Victor had been seen foraging for food in the gardens of the locals in the area and sometimes accepted people’s direct offers of food before his final capture. Eventually, he was brought to Paris and expected to answer some profound questions about the nature of human, but that goal was quashed very soon. A young physician Jean Marc Gaspard Itard was optimistic about the future of Victor and initiated a five-year education plan to civilise him and teach him to speak. With a subsidy from the government, Itard recruited a local woman Madame Guerin to assist him to provide a semblance of a home for Victor, and he spent an enormous amount of time and effort working with Victor. Itard’s goal to teach Victor the basics of speech could never be fully achieved, but Victor had learnt some elementary forms of communication."},{"label":"F","text":"Although other educators were beginning to recognise the simple truth embedded in Rousseau’s philosophy, it is not enough to identify the stages of children’s development alone. There must be certain education which had to be geared towards those stages. One of the early examples was the invention of kindergarten, which was a word and a movement created by a German-born educator, Friedrich Froebel in 1840. Froebel placed a high value on the importance of play in children’s learning. His invention would spread around the world eventually in a variety of forms. Froebel’s ideas were inspired through his cooperation with Johann Heinrich Pestalozzi. Froebel didn’t introduce the notion of kindergarten until 58 years old, and he had been a teacher for four decades. The notion was a haven and a preparation for children who were about to enter the regimented educational system. The use of guided or structured play was a cornerstone of his kindergarten education because he believed that play was the most significant aspect of development at this time of life. Play served as a mechanism for a child to grow emotionally and to achieve a sense of self-worth. Meanwhile, teachers served to organise materials and a structured environment in which each child, as an individual, could achieve these goals. When Froebel died in 1852, dozens of kindergartens had been created in Germany. Kindergartens began to increase in Europe, and the movement eventually reached and flourished in the United States in the 20th century."}],"groups":[{"intro":"Questions 1–4. Choose the correct heading for paragraphs A, C, D and E. (Example: Paragraph B – ii) List of headings: i The inheritance and development of educational concepts of different thinkers · ii Why children had to work to alleviate the burden on family · iii Why children are not highly valued · iv The explanation for children dying in hospital at their early age · v The first appearance of modern educational philosophy · vi The application of a creative learning method on a wild kid · vii The emergence and spread of the notion of kindergarten","type":"letter","opts":["i","ii","iii","iv","v","vi","vii"],"items":[["Paragraph A","iii"],["Paragraph C","v"],["Paragraph D","i"],["Paragraph E","vi"]]},{"intro":"Questions 5–8. Match each event with the correct period, A, B or C. List of periods: A the 18th century (1700–1799) · B the 19th century (1800–1899) · C the 20th century (1900–1999)","type":"letter","opts":["A","B","C"],"items":[["the need for children to work","A"],["the rise of the middle class","B"],["the emergence of a kindergarten","B"],["the spread of kindergartens around the U.S.","C"]]},{"intro":"Questions 9–13. Match each opinion or deed with the correct person, A–D. You may use any letter more than once. List of people: A Jean Jacques Rousseau · B Johan Heinrich Pestalozzi · C Jean Marc Gaspard Itard · D Friedrich Froebel","type":"letter","opts":["A","B","C","D"],"items":[["was not successful to prove the theory","C"],["observed a child’s record","A"],["requested a study setting with emotional comfort firstly","B"],["proposed that corruption was not a characteristic in people’s nature","A"],["was responsible for an increase in the number of a type of school","D"]]}]},{"id":"deserts","title":"How Deserts Are Formed","source":"Test 4 – Passage 2","paras":[{"label":"A","text":"A desert refers to a barren section of land, mainly in arid and semi-arid areas, where there is almost no precipitation, and the environment is hostile for any creature to inhabit. Deserts have been classified in a number of ways, generally combining total precipitation, how many days the rainfall occurs, temperature, humidity, and sometimes additional factors. In some places, deserts have clear boundaries marked by rivers, mountains or other landforms, while in other places, there are no clear-cut borders between desert and other landscape features."},{"label":"B","text":"In arid areas where there is not any covering of vegetation protecting the land, sand and dust storms will frequently take place. This phenomenon often occurs along the desert margins instead of within the deserts, where there are already no finer materials left. When a steady wind starts to blow, fine particles on the open ground will begin vibrating. As the wind picks up, some of the particles are lifted into the air. When they fall onto the ground, they hit other particles which will then be jerked into the air in their turn, initiating a chain reaction."},{"label":"C","text":"There has been a tremendous deal of publicity on how severe desertification can be, but the academic circle has never agreed on the causes of desertification. A common misunderstanding is that a shortage of precipitation causes the desertification—even the land in some barren areas will soon recover after the rain falls. In fact, more often than not, human activities are responsible for desertification. It might be true that the explosion in world population, especially in developing countries, is the primary cause of soil degradation and desertification. Since the population has become denser, the cultivation of crops has gone into progressively drier areas. It’s especially possible for these regions to go through periods of severe drought, which explains why crop failures are common. The raising of most crops requires the natural vegetation cover to be removed first; when crop failures occur, extensive tracts of land are devoid of a plant cover and thus susceptible to wind and water erosion. All through the 1990s, dryland areas went through a population growth of 18.5 per cent, mostly in severely impoverished developing countries."},{"label":"D","text":"Livestock farming in semi-arid areas accelerates the erosion of soil and becomes one of the reasons for advancing desertification. In such areas where the vegetation is dominated by grasses, the breeding of livestock is a major economic activity. Grasses are necessary for anchoring barren topsoil in a dryland area. When a specific field is used to graze an excessive herd, it will experience a loss in vegetation coverage, and the soil will be trampled as well as be pulverised, leaving the topsoil exposed to destructive erosion elements such as winds and unexpected thunderstorms. For centuries, nomads have grazed their flocks and herds to any place where pasture can be found, and oases have offered chances for a more settled way of living. For some nomads, wherever they move to, the desert follows."},{"label":"E","text":"Trees are of great importance when it comes to maintaining topsoil and slowing down the wind speed. In many Asian countries, firewood is the chief fuel used for cooking and heating, which has caused uncontrolled clear-cutting of forests in dryland ecosystems. When too many trees are cut down, windstorms and dust storms tend to occur."},{"label":"F","text":"What’s worse, even political conflicts and wars can also contribute to desertification. To escape from the invading enemies, the refugees will move altogether into some of the most vulnerable ecosystems on the planet. They bring along their cultivation traditions, which might not be the right kind of practice for their new settlement."},{"label":"G","text":"In the 20th century, one of the states of America had a large section of farmland that had turned into desert. Since then, actions have been enforced so that such a phenomenon of desertification will not happen again. To avoid the reoccurring of desertification, people shall find other livelihoods which do not rely on traditional land uses, are not as demanding on local land and natural resource, but can still generate viable income. Such livelihoods include but are not limited to dryland aquaculture for the raising of fish, crustaceans and industrial compounds derived from microalgae, greenhouse agriculture, and activities that are related to tourism. Another way to prevent the reoccurring of desertification is bringing about economic prospects in the city centres of drylands and places outside drylands. Changing the general economic and institutional structures that generate new chances for people to support themselves would alleviate the current pressures accompanying the desertification processes."},{"label":"H","text":"In nowadays society, new technologies are serving as a method to resolve the problems brought by desertification. Satellites have been utilised to investigate the influence that people and livestock have on our planet Earth. Nevertheless, it doesn’t mean that alternative technologies are not needed to help with the problems and process of desertification."}],"groups":[{"intro":"Questions 14–20. Which paragraph (A–H) contains the following information? You may use any letter more than once.","type":"letter","opts":["A","B","C","D","E","F","G","H"],"items":[["a reference to the irregular movement of particles","B"],["mention of a productive land turning into a desert in the 20th century","G"],["types of deserts","A"],["mention of technical methods used to tackle the problems of deserts","H"],["the influence of migration on desertification","D"],["lack of agreement among the scientists about the causes of desertification","C"],["a description of the fatal effects of farming practice","C"]]},{"intro":"Questions 21–26. Do the statements agree with the information in the passage? TRUE / FALSE / NOT GIVEN","type":"tfng","items":[["It is difficult to ascertain where the deserts end in some areas.","TRUE"],["Media is uninterested in the problems of desertification.","FALSE"],["The most common cause of desertification is the lack of rainfall.","FALSE"],["Farming animals in semi-arid areas will increase soil erosion.","TRUE"],["People in Asian countries no longer use firewood as the chief fuel.","NOT GIVEN"],["Technology studying the relationship of people, livestock and desertification has not yet been invented.","FALSE"]]}]},{"id":"torch","title":"The Olympic Torch","source":"Test 4 – Passage 3","paras":[{"label":"","text":"Since 776 B.C., when the Greek people held their first-ever Olympic Games, the Games were hosted every four years at the Olympia city. Back then, a long journey for the Olympic torch was made before the opening ceremony of each Olympic Games. The Greek people would light a cauldron of flames on the altar, a ritual devoted to Hera, the Greek Goddess of birth and marriage."},{"label":"","text":"The reintroduction of flame to the Olympics occurred at the Amsterdam 1928 Games, for which a cauldron was lit yet without a torch relay. The 1936 Berlin Summer Games held the first Olympic torch relay, which was not resumed in the Winter Olympics until in 1952. However, in that year the torch was lit not in Olympia, Greece, but in Norway, which was considered as the birthplace of skiing. Until the Innsbruck 1964 Winter Olympics in Austria, the Olympic flame was reignited at Olympia."},{"label":"","text":"The torch is originally an abstract concept of a designer or groups of designers. A couple of design groups hand in their drafts to the Olympic Committee in the hope that they would get the chance to create the torch. The group that wins the competition will come up with a design for a torch that has both aesthetic and practical value. After the torch is completed, it has to succeed in going through all sorts of severe weather conditions. The appearance of the modern Olympic torch is attributed to a Disney artist John Hench, who designed the torch for the 1960 Winter Olympics in Squaw Valley, California. His design laid a solid foundation for all the torches in the future."},{"label":"","text":"The long trip to the Olympic area is not completed by one single torch, but by thousands of them, so the torch has to be replicated many times. Approximately 10,000 to 15,000 torches are built to fit thousands of runners who take the torches through every section of the Olympic relay. Every single runner can choose to buy his or her torch as a treasurable souvenir when he or she finishes his or her part of the relay."},{"label":"","text":"The first torch in the modern Olympics (the 1936 Berlin Games) was made from a slender steel rod with a circular platform at the top and a circular hole in the middle to jet flames. The name of the runner was also inscribed on the platform as a token of thanks. In the earlier days, torches used everything from gunpowder to olive oil as fuels. Some torches adopted a combination of hexamine and naphthalene with a flammable fluid. However, these materials weren’t exactly the ideal fuel sources, and they could be quite hazardous sometimes. In the 1956 Olympics, the torch in the final relay was ignited by magnesium and aluminium, but some flaming pieces fell off and seared the runner’s arms."},{"label":"","text":"To promote the security rate, liquid fuels made its first appearance at the 1972 Munich Games. Since then, torches have been using fuels which are pressurised into the form of a liquid. When the fuels are burnt, they turn into gas to produce a flame. Liquid fuel becomes safer for the runner and can be stored in a light container. The torch at the 1996 Atlanta Summer Olympics is equipped with an aluminium base that accommodates a tiny fuel tank. As the fuel ascends through the modified handle, it is squeezed through a brass valve that has thousands of little openings. As the fuel passes through the tiny openings, it accumulates pressure. Once it makes its way through the openings, the pressure decreases and the liquid becomes gas so it can burn up."},{"label":"","text":"The torch in 1996 was fuelled by propylene, a type of substance that could give out a bright flame. However, since propylene was loaded with carbon, it would produce plenty of smoke which was detrimental to the environment. In 2000, the designers of the Sydney Olympic torch proposed a lighter and cheaper design, which was harmless to the environment. For the fuel, they decided to go with a combination of 35 per cent propane (a gas that is used for cooking and heating) and 65 per cent butane (a gas that is obtained from petroleum), thus creating a powerful flame without generating much smoke."},{"label":"","text":"Both the 1996 and 2000 torches adopted a double flame burning system, enabling the flames to stay lit even in severe weather conditions. The exterior flame burns at a slower rate and at a lower temperature. It can be perceived easily with its big orange flame, but it is unstable. On the other hand, the interior flame burns faster and hotter, generating a small blue flame with great stability, due to the internal site offering protection of it from the wind. Accordingly, the interior flame would serve as a pilot light, which could relight the external flame if it should go out."},{"label":"","text":"As for the torch of 2002 Olympics in Salt Lake City, the top section was made of glass in which the flame burned, for the purpose of echoing the theme of ‘Light the Fire Within’ of that Olympics. This torch was of great significance for the following designs of the torches."}],"groups":[{"intro":"Questions 27–29. Complete the summary. Write NO MORE THAN THREE WORDS from the passage.","type":"gap","items":[["The Olympic torch, as requested by the Olympic Committee, will be carefully designed so that it is capable of withstanding all kinds of ____.",["severe weather conditions","severe weather"]],["Generally, the design of the modern Olympic torch enjoys the ____ value.",["aesthetic and practical","both aesthetic and practical"]],["Each runner has an opportunity to purchase the torch as a(n) ____ at the end of his or her leg of the relay.",["souvenir","treasurable souvenir","a souvenir","a treasurable souvenir"]]]},{"intro":"Questions 30–35. Match each statement with the correct Olympic torch, A–H. List of Olympic torches: A ancient Greek Olympic flames · B Berlin Games torch (1936) · C 1952 Winter Games flame · D 1956 Games torch · E Munich Games torch (1972) · F 1996 torch (Atlanta) · G 2000 torch (Sydney) · H 2002 torch (Salt Lake City)","type":"letter","opts":["A","B","C","D","E","F","G","H"],"items":[["first liquid fuel","E"],["not environmentally friendly","F"],["beginning to record the runners’ name","B"],["potentially risky as it burnt the runner’s arms","D"],["special for a theme of ‘Light’","H"],["not lit in Greece","C"]]},{"intro":"Questions 36–40. Label the diagram “The structure of the 1996 and 2000 Olympic torches” (from the bottom of the torch to the top). Write NO MORE THAN THREE WORDS from the passage.","type":"gap","items":[["(bottom) ____ coated by aluminium base",["fuel tank","a fuel tank","tiny fuel tank","a tiny fuel tank"]],["a brass valve with many small ____",["openings"]],["pressurised fuel rises from the improved ____",["handle"]],["the liquid fuel mix of ____ stored in the tank",["propane and butane","butane and propane"]],["(top) burner system of a ____",["double flame","double flame burning system"]]]}]}];
